    def _join_runtime_owned_threads_for_test(self) -> None:
        runtime_thread_prefixes = (
            "organization-asset-warmup",
            "excel-intake-",
            "plan-hydration-",
            "continue-stage2-",
            "provider-webhook-event",
            "hosted-workflow-",
            "hosted-stage2-",
            "harvest-profile-run-watch-",
            "progress-auto-takeover-",
            "workflow-job-lease-",
            "workflow-runtime-controls-",
            "job-recovery-",
            "worker-recovery-daemon-thread",
            "shared-recovery-deferred-",
            "hosted-runtime-watchdog-deferred-",
            "background-snapshot-materialization-",
            "background-outreach-layering-",
        )
        for _ in range(20):
            active_runtime_threads = [
                item
                for item in threading.enumerate()
                if item.is_alive() and any(item.name.startswith(prefix) for prefix in runtime_thread_prefixes)
            ]
            if not active_runtime_threads:
                return
            for active_thread in active_runtime_threads:
                active_thread.join(timeout=0.1)
            time.sleep(0.05)

    def _write_company_snapshot_candidate_documents(
        self,
        *,
        target_company: str,
        snapshot_id: str,
        candidates: list[dict[str, object]],
    ) -> tuple[Path, Path]:
        normalized_key = normalize_company_key(target_company)
        company_key = canonicalize_company_key(target_company) or normalized_key
        identity = {
            "requested_name": target_company,
            "canonical_name": target_company,
            "company_key": company_key,
            "linkedin_slug": company_key,
            "aliases": [normalized_key] if normalized_key and normalized_key != company_key else [],
        }
        snapshot_dir = self.settings.company_assets_dir / company_key / snapshot_id
        snapshot_dir.mkdir(parents=True, exist_ok=True)
        candidate_doc_path = snapshot_dir / "candidate_documents.json"
        candidate_doc_path.write_text(
            json.dumps(
                {
                    "snapshot": {
                        "target_company": target_company,
                        "snapshot_id": snapshot_id,
                        "company_identity": identity,
                    },
                    "target_company": target_company,
                    "snapshot_id": snapshot_id,
                    "candidates": candidates,
                    "evidence": [],
                    "candidate_count": len(candidates),
                    "evidence_count": 0,
                },
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
        (snapshot_dir / "identity.json").write_text(
            json.dumps(identity, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        (snapshot_dir / "manifest.json").write_text(
            json.dumps(
                {
                    "snapshot_id": snapshot_id,
                    "company_identity": identity,
                },
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
        return snapshot_dir, candidate_doc_path

    def _seed_canonical_lifecycle_for_test(self, job_id: str) -> dict[str, object]:
        """Seed a canonical lifecycle row for public-read tests.

        This is intentionally test setup, not a production fallback. Public
        reads must consume the row as written here and must not reconstruct it
        from job/result/candidate-source payloads.
        """

        job = self.store.get_job(job_id) or {}
        result_view = self.store.get_job_result_view(job_id=job_id) or {}
        job_summary = dict(job.get("summary") or {})
        request = JobRequest.from_payload(dict(job.get("request") or {}))
        view_metadata = dict(result_view.get("metadata") or {})
        serialized_lifecycle = dict(
            view_metadata.get("result_view_lifecycle") or job_summary.get("result_view_lifecycle") or {}
        )
        if serialized_lifecycle:
            fields = dict(serialized_lifecycle)
            fields["source_validation_status"] = "validated"
        else:
            candidate_source = dict(job_summary.get("candidate_source") or {})
            result_view_summary = dict(result_view.get("summary") or {})
            served_snapshot_id = str(result_view.get("snapshot_id") or candidate_source.get("snapshot_id") or "").strip()
            served_candidate_count = int(
                result_view_summary.get("candidate_count") or candidate_source.get("candidate_count") or 0
            )
            baseline_snapshot_id = str(
                dict(request.execution_preferences or {}).get("delta_baseline_snapshot_id") or ""
            ).strip()
            baseline_candidate_count = 0
            if baseline_snapshot_id:
                for row in self.store.list_organization_asset_registry(
                    target_company=str(request.target_company or ""),
                    asset_view=str(candidate_source.get("asset_view") or result_view.get("asset_view") or "canonical_merged"),
                    limit=50,
                ):
                    if str(dict(row).get("snapshot_id") or "").strip() == baseline_snapshot_id:
                        baseline_candidate_count = int(dict(row).get("candidate_count") or 0)
                        break
            stage1_preview = dict(job_summary.get("stage1_preview") or {})
            stage1_source = dict(stage1_preview.get("candidate_source") or {})
            if (
                baseline_snapshot_id
                and baseline_candidate_count <= 0
                and str(stage1_source.get("snapshot_id") or "").strip() == baseline_snapshot_id
            ):
                baseline_candidate_count = int(
                    stage1_source.get("candidate_count")
                    or stage1_preview.get("returned_matches")
                    or stage1_preview.get("total_matches")
                    or 0
                )
            current_snapshot_id = served_snapshot_id
            state = (
                "baseline_serving"
                if baseline_snapshot_id and served_snapshot_id == baseline_snapshot_id
                else "current_snapshot_serving"
            )
            fields = {
                "state": state,
                "phase": state,
                "baseline_snapshot_id": baseline_snapshot_id,
                "current_snapshot_id": current_snapshot_id,
                "served_snapshot_id": served_snapshot_id,
                "baseline_candidate_count": baseline_candidate_count,
                "served_candidate_count": served_candidate_count,
                "expected_candidate_count": max(served_candidate_count, baseline_candidate_count),
                "delta_profile_progress_applicable": bool(baseline_snapshot_id),
                "delta_profile_progress_reason": "linkedin_stage_1_progress" if baseline_snapshot_id else "",
                "source_validation_status": "validated",
            }
        self.store.upsert_job_result_lifecycle(job_id=job_id, fields=fields)
        row = self.store.get_job_result_lifecycle(job_id)
        self.assertIsNotNone(row)
        return dict(row or {})

    def _write_materialized_snapshot_view(
        self,
        *,
        target_company: str,
        snapshot_id: str,
        candidates: list[dict[str, object]],
        view: str = "canonical_merged",
        page_size: int = 50,
    ) -> Path:
        company_key = normalize_company_key(target_company)
        company_dir = Path(self.tempdir.name) / "company_assets" / company_key
        snapshot_dir = company_dir / snapshot_id
        normalized_dir = snapshot_dir / "normalized_artifacts"
        view_dir = normalized_dir if view == "canonical_merged" else (normalized_dir / view)
        (view_dir / "pages").mkdir(parents=True, exist_ok=True)
        (view_dir / "candidates").mkdir(parents=True, exist_ok=True)
        view_dir.mkdir(parents=True, exist_ok=True)

        company_identity = {
            "requested_name": target_company,
            "canonical_name": target_company,
            "company_key": company_key,
        }
        (company_dir / "latest_snapshot.json").write_text(
            json.dumps(
                {
                    "snapshot_id": snapshot_id,
                    "company_identity": company_identity,
                },
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
        (snapshot_dir / "manifest.json").write_text(
            json.dumps(
                {
                    "snapshot_id": snapshot_id,
                    "company_identity": company_identity,
                },
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
        (view_dir / "materialized_candidate_documents.json").write_text(
            json.dumps(
                {
                    "snapshot": {
                        "snapshot_id": snapshot_id,
                        "company_identity": company_identity,
                    },
                    "candidates": list(candidates or []),
                    "evidence": [],
                    "candidate_count": len(list(candidates or [])),
                    "evidence_count": 0,
                },
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
        (view_dir / "artifact_summary.json").write_text(
            json.dumps(
                {
                    "target_company": target_company,
                    "snapshot_id": snapshot_id,
                    "asset_view": view,
                    "candidate_count": len(list(candidates or [])),
                    "evidence_count": 0,
                    "candidate_page_size": page_size,
                    "candidate_page_count": max((len(list(candidates or [])) + page_size - 1) // page_size, 0),
                },
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
        page_entries: list[dict[str, object]] = []
        shard_entries: list[dict[str, object]] = []
        publishable_lookup = {
            "target_company": target_company,
            "snapshot_id": snapshot_id,
            "asset_view": view,
            "by_candidate_id": {},
            "by_profile_url_key": {},
        }
        for index, candidate in enumerate(list(candidates or [])):
            candidate_id = str(candidate.get("candidate_id") or "").strip()
            page_number = (index // page_size) + 1 if page_size > 0 else 1
            shard_path = f"candidates/{candidate_id}.fixture.json"
            shard_entries.append(
                {
                    "candidate_id": candidate_id,
                    "fingerprint": "fixture",
                    "path": shard_path,
                    "page": page_number,
                    "display_name": str(candidate.get("display_name") or ""),
                    "status_bucket": str(candidate.get("status_bucket") or ""),
                    "has_profile_detail": bool(candidate.get("has_profile_detail")),
                    "needs_manual_review": bool(candidate.get("needs_manual_review")),
                    "needs_profile_completion": bool(candidate.get("needs_profile_completion")),
                }
            )
            (view_dir / shard_path).write_text(
                json.dumps(
                    {
                        "candidate_id": candidate_id,
                        "snapshot_id": snapshot_id,
                        "asset_view": view,
                        "materialized_candidate": dict(candidate),
                        "normalized_candidate": dict(candidate),
                        "reusable_document": {
                            "candidate_id": candidate_id,
                            "display_name": str(candidate.get("display_name") or ""),
                        },
                        "evidence": list(candidate.get("evidence") or []),
                    },
                    ensure_ascii=False,
                    indent=2,
                ),
                encoding="utf-8",
            )
            metadata = dict(candidate.get("metadata") or {})
            primary_email = str(
                candidate.get("primary_email")
                or candidate.get("email")
                or metadata.get("primary_email")
                or metadata.get("email")
                or ""
            ).strip()
            if primary_email:
                overlay = {
                    "primary_email": primary_email,
                }
                primary_email_metadata = candidate.get("primary_email_metadata") or metadata.get(
                    "primary_email_metadata"
                )
                if isinstance(primary_email_metadata, dict) and primary_email_metadata:
                    overlay["primary_email_metadata"] = dict(primary_email_metadata)
                publishable_lookup["by_candidate_id"][candidate_id] = dict(overlay)
                linkedin_url = normalize_linkedin_profile_url_key(
                    str(candidate.get("linkedin_url") or "").strip()
                )
                if linkedin_url:
                    publishable_lookup["by_profile_url_key"][linkedin_url] = dict(overlay)
        for page_index in range(0, len(list(candidates or [])), page_size):
            page_number = (page_index // page_size) + 1 if page_size > 0 else 1
            page_candidates = list(candidates or [])[page_index : page_index + page_size]
            relative_path = f"pages/page-{page_number:04d}.json"
            page_entries.append(
                {
                    "page": page_number,
                    "path": relative_path,
                    "candidate_count": len(page_candidates),
                }
            )
            (view_dir / relative_path).write_text(
                json.dumps(
                    {
                        "target_company": target_company,
                        "snapshot_id": snapshot_id,
                        "asset_view": view,
                        "page": page_number,
                        "page_size": page_size,
                        "candidate_count": len(page_candidates),
                        "total_candidate_count": len(list(candidates or [])),
                        "candidates": list(page_candidates),
                    },
                    ensure_ascii=False,
                    indent=2,
                ),
                encoding="utf-8",
            )
        (view_dir / "manifest.json").write_text(
            json.dumps(
                {
                    "target_company": target_company,
                    "company_key": company_key,
                    "snapshot_id": snapshot_id,
                    "asset_view": view,
                    "candidate_count": len(list(candidates or [])),
                    "pagination": {
                        "page_size": page_size,
                        "page_count": len(page_entries),
                    },
                    "candidate_shards": shard_entries,
                    "pages": page_entries,
                    "backlogs": {
                        "manual_review": "backlogs/manual_review.json",
                        "profile_completion": "backlogs/profile_completion.json",
                    },
                    "auxiliary": {
                        "publishable_primary_emails": "publishable_primary_emails.json",
                    },
                },
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
        (view_dir / "publishable_primary_emails.json").write_text(
            json.dumps(publishable_lookup, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        return snapshot_dir

    def test_projection_api_reads_canonical_projection_members_without_legacy_fallback(self) -> None:
        self.orchestrator.serving_projection_writer.publish_run_scope_projection(
            run_id="job-projection-api",
            collection_id="company:openai",
            projection_id="proj_api_canonical",
            members=[
                {
                    "candidate_identity_key": "linkedin:proj-api",
                    "person_identity_key": "linkedin:proj-api",
                    "rank_index": 1,
                    "public_summary": {
                        "name": "Projection API",
                        "primary_email": "hidden@example.com",
                        "raw_profile": {"hidden": True},
                    },
                    "projection_metrics": {"row_readiness": "ready"},
                    "crm_overlay_summary": {"in_crm": False},
                }
            ],
            replace_members=True,
            counts={"result_count": 1, "count_scope": "exact_projection"},
        )

        server = create_server(self.orchestrator, host="127.0.0.1", port=0)
        thread = threading.Thread(target=server.serve_forever, daemon=True)
        thread.start()
        host, port = server.server_address
        opener = urllib_request.build_opener(urllib_request.ProxyHandler({}))
        try:
            with opener.open(f"http://{host}:{port}/api/runs/job-projection-api/projection-link") as response:
                link_payload = json.loads(response.read().decode("utf-8"))
            with opener.open(f"http://{host}:{port}/api/projections/proj_api_canonical") as response:
                projection_payload = json.loads(response.read().decode("utf-8"))
            with opener.open(
                f"http://{host}:{port}/api/projections/proj_api_canonical/candidates?offset=0&limit=10"
            ) as response:
                page_payload = json.loads(response.read().decode("utf-8"))
            try:
                opener.open(f"http://{host}:{port}/api/projections/proj_missing/candidates")
            except urllib_error.HTTPError as exc:
                missing_status = exc.code
                missing_payload = json.loads(exc.read().decode("utf-8"))
            else:
                self.fail("missing projection should fail closed")
        finally:
            server.shutdown()
            server.server_close()
            thread.join(timeout=5)

        self.assertEqual(link_payload["projection_id"], "proj_api_canonical")
        self.assertEqual(projection_payload["projection"]["projection_id"], "proj_api_canonical")
        self.assertEqual(projection_payload["projection"]["read_contract"]["source"], "serving_projection_members")
        self.assertFalse(projection_payload["projection"]["read_contract"]["fallback_used"])
        self.assertEqual(page_payload["total_candidates"], 1)
        self.assertEqual(page_payload["candidates"][0]["public_summary"]["name"], "Projection API")
        self.assertNotIn("primary_email", page_payload["candidates"][0]["public_summary"])
        self.assertNotIn("raw_profile", page_payload["candidates"][0]["public_summary"])
        self.assertEqual(missing_status, 404)
        self.assertEqual(missing_payload["error"], "projection not found")

