        stored_projection = dict(dict(stored_view.get("metadata") or {}).get("run_scope_projection") or {})
        stored_command = self.store.get_workflow_command(str(command.get("command_id") or "")) or {}

        self.assertEqual(dict(recovery.get("run_scope_projection_finalize") or {}).get("completed_count"), 1)
        self.assertEqual(dict(recovery.get("run_scope_projection_finalize") or {}).get("executed_command_count"), 1)
