    def test_partial_serving_projection_cannot_override_baseline_delta_lifecycle(self) -> None:
        raw_lifecycle = {
            "state": "current_snapshot_serving",
            "baseline_snapshot_id": "20260511T000000",
            "current_snapshot_id": "20260521Tpartial",
            "served_snapshot_id": "20260521Tpartial",
            "baseline_candidate_count": 8711,
            "expected_candidate_count": 8831,
            "served_candidate_count": 8831,
        }
        partial_projection_payload = {
            "status": "ready",
            "projection": {
                "projection_id": "proj_partial",
                "visible_member_count": 6083,
                "readiness": {"row": "complete", "row_count": 6083},
            },
        }

        unchanged = self.orchestrator._normalize_public_lifecycle_to_serving_projection(
            result_view_lifecycle=raw_lifecycle,
            serving_projection_payload=partial_projection_payload,
        )

        self.assertEqual(unchanged["served_candidate_count"], 8831)
        self.assertEqual(unchanged["expected_candidate_count"], 8831)
        self.assertEqual(unchanged["metadata"]["partial_serving_projection_visible_member_count"], 6083)

        complete_projection_payload = {
            "status": "ready",
            "projection": {
                "projection_id": "proj_complete",
                "visible_member_count": 8830,
                "readiness": {"row": "complete", "row_count": 8830},
            },
        }

        normalized = self.orchestrator._normalize_public_lifecycle_to_serving_projection(
            result_view_lifecycle=raw_lifecycle,
            serving_projection_payload=complete_projection_payload,
        )

        self.assertEqual(normalized["served_candidate_count"], 8830)
        self.assertEqual(normalized["expected_candidate_count"], 8830)
        self.assertEqual(
            normalized["metadata"]["canonical_projection_public_count_normalization"]["visible_member_count"],
            8830,
        )

