    def test_job_progress_compacts_large_polling_payloads(self) -> None:
        job_id = "job_progress_compact_polling_payload"
        huge_urls = [f"https://www.linkedin.com/in/meta-agent-{index}" for index in range(500)]
        self.store.save_job(
            job_id=job_id,
            job_type="workflow",
            status="completed",
            stage="completed",
            request_payload={
                "raw_user_request": "帮我找Meta做Agent方向的人",
                "target_company": "Meta",
                "target_scope": "full_company_asset",
            },
            plan_payload={
                "acquisition_strategy": {
                    "provider_execution_manifest": {
                        "version": 1,
                        "source": "planning_contract",
                        "strategy_type": "scoped_search_roster",
                        "lanes": [
                            {
                                "lane_id": "current_profile_search",
                                "employment_status": "current",
                                "provider": "harvest_profile_search",
                                "operation": "profile_search",
                                "query_texts": ["Agent"],
                                "company_filters": {"current_companies": ["Meta"]},
                                "provider_facing_query": True,
                                "display_label": "Harvest profile search",
                                "reason": "scoped_keyword_profile_search",
                            }
                        ],
                    }
                }
            },
            summary_payload={
                "message": "Local asset population is ready.",
                "candidate_source": {
                    "source_kind": "company_snapshot",
                    "snapshot_id": "20260427T203601",
                    "asset_view": "canonical_merged",
                    "candidate_count": 1727,
                },
                "background_reconcile": {
                    "harvest_prefetch": {
                        "status": "completed",
                        "deferred_urls": huge_urls,
                    }
                },
            },
        )
        stage_summaries = {
            "summaries": {
                "stage_2_final": {
                    "status": "completed",
                    "text": "Workflow completed.",
                    "background_reconcile": {
                        "harvest_prefetch": {
                            "status": "completed",
                            "deferred_urls": huge_urls,
                        }
                    },
                }
            }
        }

        with mock.patch.object(self.orchestrator, "_load_workflow_stage_summaries", return_value=stage_summaries):
            progress = self.orchestrator.get_job_progress(job_id)

        assert progress is not None
        self.assertEqual(progress["provider_execution_manifest"]["lanes"][0]["query_texts"], ["Agent"])
        self.assertEqual(progress["progress"]["provider_execution_manifest"], progress["provider_execution_manifest"])
        self.assertLess(len(json.dumps(progress)), 100_000)
        self.assertEqual(
            progress["progress"]["latest_metrics"]["background_reconcile"]["harvest_prefetch"][
                "deferred_url_count"
            ],
            500,
        )
        self.assertEqual(
            progress["workflow_stage_summaries"]["summaries"]["stage_2_final"]["background_reconcile"][
                "harvest_prefetch"
            ]["deferred_url_count"],
            500,
        )
        self.assertNotIn(
            "deferred_urls",
            progress["progress"]["latest_metrics"]["background_reconcile"]["harvest_prefetch"],
        )
        self.assertNotIn(
            "summary_path",
            progress["workflow_stage_summaries"]["summaries"]["stage_2_final"],
        )

    def test_delta_workflow_publishes_baseline_serving_result_view_before_materialization(self) -> None:
        baseline_snapshot_id = "20260420T120000"
        self._write_materialized_snapshot_view(
            target_company="OpenAI",
            snapshot_id=baseline_snapshot_id,
            candidates=[
                {
                    "candidate_id": "baseline_agent_1",
                    "display_name": "Baseline Agent One",
                    "name_en": "Baseline Agent One",
                    "target_company": "OpenAI",
                    "organization": "OpenAI",
                    "employment_status": "current",
                    "role": "Research Engineer",
                    "linkedin_url": "https://www.linkedin.com/in/baseline-agent-one/",
                },
                {
                    "candidate_id": "baseline_agent_2",
                    "display_name": "Baseline Agent Two",
                    "name_en": "Baseline Agent Two",
                    "target_company": "OpenAI",
                    "organization": "OpenAI",
                    "employment_status": "former",
                    "role": "Research Scientist",
                    "linkedin_url": "https://www.linkedin.com/in/baseline-agent-two/",
                },
            ],
        )
        request = JobRequest.from_payload(
            {
                "raw_user_request": "帮我找OpenAI做Agent方向的人",
                "target_company": "OpenAI",
                "keywords": ["Agent"],
                "employment_statuses": ["current", "former"],
                "execution_preferences": {
                    "delta_baseline_snapshot_id": baseline_snapshot_id,
                },
            }
        )
        plan = hydrate_sourcing_plan(self.orchestrator.plan_workflow(request.to_record())["plan"])
        plan.asset_reuse_plan = {
            "baseline_reuse_available": True,
            "requires_delta_acquisition": True,
            "planner_mode": "baseline_reuse_with_delta",
            "baseline_snapshot_id": baseline_snapshot_id,
            "baseline_candidate_count": 2,
        }

        job_id = self.orchestrator._create_workflow_job(request, plan)  # noqa: SLF001

        result_view = self.store.get_job_result_view(job_id=job_id)
        assert result_view is not None
        self.assertEqual(result_view["snapshot_id"], baseline_snapshot_id)
        lifecycle = dict(dict(result_view.get("metadata") or {}).get("result_view_lifecycle") or {})
        self.assertEqual(lifecycle["state"], "baseline_serving")
        self.assertEqual(lifecycle["served_candidate_count"], 2)

        dashboard = self.orchestrator.get_job_dashboard(job_id)
        assert dashboard is not None
        self.assertTrue(dashboard["asset_population"]["available"])
        self.assertEqual(dashboard["asset_population"]["snapshot_id"], baseline_snapshot_id)
        self.assertEqual(dashboard["asset_population"]["candidate_count"], 2)
        self.assertEqual(dashboard["asset_population"]["candidate_source"]["snapshot_id"], baseline_snapshot_id)
        self.assertEqual(
            dashboard["asset_population"]["candidate_source"]["result_view"]["snapshot_id"],
            baseline_snapshot_id,
        )
        self.assertEqual(dashboard["result_view_lifecycle"]["state"], "baseline_serving")
        self.assertEqual(dashboard["result_view_lifecycle"]["served_candidate_count"], 2)

