    def test_delta_progress_exposes_search_and_profile_fetch_counts(self) -> None:
        baseline_snapshot_id = "20260420T121500"
        self._write_materialized_snapshot_view(
            target_company="OpenAI",
            snapshot_id=baseline_snapshot_id,
            candidates=[
                {
                    "candidate_id": "baseline_agent",
                    "display_name": "Baseline Agent",
                    "name_en": "Baseline Agent",
                    "target_company": "OpenAI",
                    "organization": "OpenAI",
                    "employment_status": "current",
                    "role": "Research Engineer",
                    "linkedin_url": "https://www.linkedin.com/in/baseline-agent/",
                }
            ],
        )
        request = JobRequest.from_payload(
            {
                "raw_user_request": "帮我找OpenAI做Agent方向的人",
                "target_company": "OpenAI",
                "keywords": ["Agent"],
                "employment_statuses": ["current", "former"],
                "execution_preferences": {
                    "delta_baseline_snapshot_id": baseline_snapshot_id,
                },
            }
        )
        plan = hydrate_sourcing_plan(self.orchestrator.plan_workflow(request.to_record())["plan"])
        plan.asset_reuse_plan = {
            "baseline_reuse_available": True,
            "requires_delta_acquisition": True,
            "planner_mode": "baseline_reuse_with_delta",
            "baseline_snapshot_id": baseline_snapshot_id,
            "baseline_candidate_count": 1,
        }
        job_id = self.orchestrator._create_workflow_job(request, plan)  # noqa: SLF001
        job = self.store.get_job(job_id)
        self.store.save_job(
            job_id=job_id,
            job_type="workflow",
            status="running",
            stage="acquiring",
            request_payload=request.to_record(),
            plan_payload=plan.to_record(),
            summary_payload=dict((job or {}).get("summary") or {}),
        )

        current_a = "https://www.linkedin.com/in/openai-agent-current-a/"
        overlap_b = "https://www.linkedin.com/in/openai-agent-overlap-b/"
        former_c = "https://www.linkedin.com/in/openai-agent-former-c/"
        search_worker = self.orchestrator.agent_runtime.begin_worker(
            job_id=job_id,
            request=request,
            plan_payload=plan.to_record(),
            runtime_mode="workflow",
            lane_id="search_planner",
            worker_key="search_seed::agent",
            stage="acquiring",
            span_name="search_seed:agent",
            budget_payload={},
            input_payload={},
            metadata={"recovery_kind": "search_seed_discovery"},
            handoff_from_lane="acquisition_specialist",
        )
        self.orchestrator.agent_runtime.complete_worker(
            search_worker,
            status="completed",
            checkpoint_payload={"stage": "completed", "recovery_kind": "search_seed_discovery"},
            output_payload={
                "entries": [
                    {"full_name": "Current A", "profile_url": current_a, "employment_status": "current"},
                    {"full_name": "Overlap B", "profile_url": overlap_b, "employment_status": "current"},
                    {"full_name": "Overlap B", "profile_url": overlap_b, "employment_status": "former"},
                    {"full_name": "Former C", "profile_url": former_c, "employment_status": "former"},
                ]
            },
        )
        completed_profile_worker = self.orchestrator.agent_runtime.begin_worker(
            job_id=job_id,
            request=request,
            plan_payload=plan.to_record(),
            runtime_mode="workflow",
            lane_id="enrichment_specialist",
            worker_key="harvest_profile_batch::agent-a",
            stage="enriching",
            span_name="harvest_profile_batch:agent-a",
            budget_payload={"requested_url_count": 1},
            input_payload={"profile_urls": [current_a]},
            metadata={"recovery_kind": "harvest_profile_batch", "profile_urls": [current_a]},
            handoff_from_lane="search_planner",
        )
        self.orchestrator.agent_runtime.complete_worker(
            completed_profile_worker,
            status="completed",
            checkpoint_payload={"stage": "completed", "recovery_kind": "harvest_profile_batch"},
            output_payload={"summary": {"status": "completed", "requested_urls": [current_a]}},
        )
        self.orchestrator.agent_runtime.begin_worker(
            job_id=job_id,
            request=request,
            plan_payload=plan.to_record(),
            runtime_mode="workflow",
            lane_id="enrichment_specialist",
            worker_key="harvest_profile_batch::agent-tail",
            stage="enriching",
            span_name="harvest_profile_batch:agent-tail",
            budget_payload={"requested_url_count": 2},
            input_payload={"profile_urls": [overlap_b, former_c]},
            metadata={"recovery_kind": "harvest_profile_batch", "profile_urls": [overlap_b, former_c]},
            handoff_from_lane="search_planner",
        )
        self.store.repos.linkedin_profile_registry.mark_fetched(current_a, raw_path="/tmp/current-a.json")
        self.store.repos.linkedin_profile_registry.mark_queued(overlap_b)
        self.store.repos.linkedin_profile_registry.mark_queued(former_c)

        progress = self.orchestrator.get_job_progress(job_id)
        assert progress is not None
        linkedin_progress = dict(progress["linkedin_stage_1_progress"])
        self.assertEqual(linkedin_progress["current_search_returned_count"], 2)
        self.assertEqual(linkedin_progress["former_search_returned_count"], 2)
        self.assertEqual(linkedin_progress["deduped_candidate_count"], 3)
        self.assertEqual(linkedin_progress["profile_fetch_required_count"], 3)
        self.assertEqual(linkedin_progress["profile_fetched_count"], 1)
        self.assertEqual(linkedin_progress["profile_queued_count"], 2)
        lifecycle = dict(progress["result_view_lifecycle"])
        self.assertEqual(lifecycle["state"], "baseline_serving")
        self.assertEqual(lifecycle["served_candidate_count"], 1)
        self.assertEqual(lifecycle["expected_candidate_count"], 1)
        self.assertTrue(lifecycle["delta_profile_progress_applicable"])
        self.assertEqual(lifecycle["delta_profile_required_count"], 0)
        self.assertEqual(lifecycle["delta_profile_fetched_count"], 0)
        self.assertEqual(lifecycle["delta_profile_materialized_count"], 0)
        row = dict(self.store.get_job_result_lifecycle(job_id) or {})
        self.assertEqual(row.get("state"), "baseline_serving")
        self.assertEqual(row.get("delta_profile_required_count"), 0)

