    def test_stage1_progress_merges_search_seed_lane_assets_when_latest_state_is_partial(self) -> None:
        request = JobRequest.from_payload(
            {
                "raw_user_request": "帮我找OpenAI做Agent方向的人",
                "target_company": "OpenAI",
                "keywords": ["Agent"],
                "employment_statuses": ["current", "former"],
            }
        )
        plan = hydrate_sourcing_plan(self.orchestrator.plan_workflow(request.to_record())["plan"])
        job_id = "job_stage1_progress_lane_asset_restore"
        snapshot_dir = Path(self.tempdir.name) / "company_assets" / "openai" / "20260430T033523"
        discovery_dir = snapshot_dir / "search_seed_discovery"
        current_dir = discovery_dir / "current"
        former_dir = discovery_dir / "former"
        current_dir.mkdir(parents=True, exist_ok=True)
        former_dir.mkdir(parents=True, exist_ok=True)
        identity = {
            "requested_name": "OpenAI",
            "canonical_name": "OpenAI",
            "company_key": "openai",
            "linkedin_slug": "openai",
        }
        (snapshot_dir / "identity.json").write_text(json.dumps(identity), encoding="utf-8")
        current_entries = [
            {
                "full_name": f"Current {index}",
                "profile_url": f"https://www.linkedin.com/in/openai-agent-current-{index}/",
                "employment_status": "current",
            }
            for index in range(1, 4)
        ]
        former_entries = [
            {
                "full_name": f"Former {index}",
                "profile_url": f"https://www.linkedin.com/in/openai-agent-former-{index}/",
                "employment_status": "former",
            }
            for index in range(1, 3)
        ]
        (discovery_dir / "summary.json").write_text(
            json.dumps(
                {
                    "snapshot_id": snapshot_dir.name,
                    "target_company": "OpenAI",
                    "company_identity": identity,
                    "entry_count": len(former_entries),
                },
                ensure_ascii=False,
            ),
            encoding="utf-8",
        )
        # Simulate the exact drift seen in browser observations: latest_state points at
        # a partial aggregate file while lane materialization has the complete split.
        (discovery_dir / "entries.json").write_text(json.dumps(former_entries, ensure_ascii=False), encoding="utf-8")
        (current_dir / "summary.json").write_text(
            json.dumps({"employment_scope": "current", "entry_count": len(current_entries)}, ensure_ascii=False),
            encoding="utf-8",
        )
        (current_dir / "entries.json").write_text(json.dumps(current_entries, ensure_ascii=False), encoding="utf-8")
        (former_dir / "summary.json").write_text(
            json.dumps({"employment_scope": "former", "entry_count": len(former_entries)}, ensure_ascii=False),
            encoding="utf-8",
        )
        (former_dir / "entries.json").write_text(json.dumps(former_entries, ensure_ascii=False), encoding="utf-8")

        self.store.save_job(
            job_id=job_id,
            job_type="workflow",
            status="running",
            stage="acquiring",
            request_payload=request.to_record(),
            plan_payload=plan.to_record(),
            summary_payload={
                "acquisition_progress": {
                    "latest_state": {
                        "snapshot_dir": str(snapshot_dir),
                        "company_identity": identity,
                        "search_seed_snapshot": {
                            "snapshot_id": snapshot_dir.name,
                            "target_company": "OpenAI",
                            "company_identity": identity,
                            "snapshot_dir": str(snapshot_dir),
                            "summary_path": str(discovery_dir / "summary.json"),
                            "entries_path": str(discovery_dir / "entries.json"),
                        },
                    }
                }
            },
        )
        profile_urls = [entry["profile_url"] for entry in [*current_entries, *former_entries]]
        self.orchestrator.agent_runtime.begin_worker(
            job_id=job_id,
            request=request,
            plan_payload=plan.to_record(),
            runtime_mode="workflow",
            lane_id="enrichment_specialist",
            worker_key="harvest_profile_batch::agent",
            stage="enriching",
            span_name="harvest_profile_batch:agent",
            budget_payload={"requested_url_count": len(profile_urls)},
            input_payload={"profile_urls": profile_urls},
            metadata={"recovery_kind": "harvest_profile_batch", "profile_urls": profile_urls},
            handoff_from_lane="search_planner",
        )
        for url in profile_urls:
            self.store.repos.linkedin_profile_registry.mark_queued(url)

        progress = self.orchestrator.get_job_progress(job_id)
        assert progress is not None
        linkedin_progress = dict(progress["linkedin_stage_1_progress"])
        self.assertEqual(linkedin_progress["current_search_returned_count"], 3)
        self.assertEqual(linkedin_progress["former_search_returned_count"], 2)
        self.assertEqual(linkedin_progress["deduped_candidate_count"], 5)
        self.assertEqual(linkedin_progress["deduped_profile_url_count"], 5)
        self.assertEqual(linkedin_progress["profile_fetch_required_count"], 5)

