    def test_result_view_lifecycle_infers_baseline_count_from_stage1_preview(self) -> None:
        baseline_snapshot_id = "20260428T183413"
        current_snapshot_id = "20260429T174612"
        self._write_materialized_snapshot_view(
            target_company="OpenAI",
            snapshot_id=baseline_snapshot_id,
            candidates=[{"candidate_id": "baseline_member", "display_name": "Baseline Member"}],
        )
        self._write_materialized_snapshot_view(
            target_company="OpenAI",
            snapshot_id=current_snapshot_id,
            candidates=[
                {"candidate_id": "baseline_member", "display_name": "Baseline Member"},
                {"candidate_id": "delta_member", "display_name": "Delta Member"},
            ],
        )
        request = JobRequest.from_payload(
            {
                "raw_user_request": "我想要OpenAI在ChatGPT组的人",
                "target_company": "OpenAI",
                "keywords": ["ChatGPT"],
                "execution_preferences": {"delta_baseline_snapshot_id": baseline_snapshot_id},
            }
        )
        job_id = "job_result_view_lifecycle_stage1_baseline_count"
        current_manifest = (
            Path(self.tempdir.name)
            / "company_assets"
            / "openai"
            / current_snapshot_id
            / "normalized_artifacts"
            / "manifest.json"
        )
        (current_manifest.parent / "artifact_summary.json").write_text(
            json.dumps({"snapshot_id": current_snapshot_id, "candidate_count": 1061}, ensure_ascii=False),
            encoding="utf-8",
        )
        self.store.save_job(
            job_id=job_id,
            job_type="workflow",
            status="completed",
            stage="completed",
            request_payload=request.to_record(),
            plan_payload={},
            summary_payload={
                "stage1_preview": {
                    "returned_matches": 890,
                    "total_matches": 890,
                    "candidate_source": {
                        "source_kind": "company_snapshot",
                        "snapshot_id": baseline_snapshot_id,
                        "asset_view": "canonical_merged",
                        "candidate_count": 890,
                    },
                },
                "candidate_source": {
                    "source_kind": "company_snapshot",
                    "snapshot_id": current_snapshot_id,
                    "asset_view": "canonical_merged",
                    "source_path": str(current_manifest),
                    "candidate_count": 1061,
                },
            },
        )
        self.store.upsert_job_result_view(
            job_id=job_id,
            target_company="OpenAI",
            source_kind="company_snapshot",
            view_kind="asset_population",
            snapshot_id=current_snapshot_id,
            asset_view="canonical_merged",
            source_path=str(current_manifest),
            summary={"candidate_count": 1061},
        )
        self._seed_canonical_lifecycle_for_test(job_id)

        dashboard = self.orchestrator.get_job_dashboard(job_id)
        assert dashboard is not None
        lifecycle = dict(dashboard["result_view_lifecycle"])
        self.assertEqual(lifecycle["baseline_snapshot_id"], baseline_snapshot_id)
        self.assertEqual(lifecycle["served_snapshot_id"], current_snapshot_id)
        self.assertEqual(lifecycle["baseline_candidate_count"], 890)
        # Per docs/JOB_RESULT_LIFECYCLE_DESIGN.md: served_candidate_count is the
        # canonical result-view summary count, sourced uniformly from
        # job_result_views.summary.candidate_count for every public reader
        # (/dashboard, /progress, /candidates). It is no longer rebuilt
        # per-caller from on-disk candidate_documents, which is what made the
        # OpenAI Infra cross-API regression possible. Here that count is 1061.
        self.assertEqual(lifecycle["served_candidate_count"], 1061)
        self.assertEqual(lifecycle["expected_candidate_count"], 1061)

