    def test_execution_phase_contract_keeps_linkedin_stage_running_while_profiles_pending(self) -> None:
        request = JobRequest.from_payload(
            {
                "raw_user_request": "我想要OpenAI在ChatGPT组的人",
                "target_company": "OpenAI",
                "keywords": ["ChatGPT"],
                "execution_preferences": {"delta_baseline_snapshot_id": "20260428T183413"},
            }
        )
        plan = hydrate_sourcing_plan(self.orchestrator.plan_workflow(request.to_record())["plan"])
        job_id = "job_execution_phase_profiles_pending"
        self.store.save_job(
            job_id=job_id,
            job_type="workflow",
            status="running",
            stage="acquiring",
            request_payload=request.to_record(),
            plan_payload=plan.to_record(),
            summary_payload={
                "stage1_preview": {
                    "status": "completed",
                    "ready_at": "2026-04-29T09:45:00Z",
                    "returned_matches": 890,
                    "candidate_source": {
                        "snapshot_id": "20260428T183413",
                        "candidate_count": 890,
                    },
                },
                "result_view_lifecycle": {
                    "state": "baseline_serving",
                    "baseline_snapshot_id": "20260428T183413",
                    "baseline_candidate_count": 890,
                    "served_candidate_count": 890,
                    "expected_candidate_count": 1061,
                },
            },
        )
        fetched_url = "https://www.linkedin.com/in/openai-chatgpt-fetched/"
        queued_url = "https://www.linkedin.com/in/openai-chatgpt-queued/"
        self.orchestrator.agent_runtime.begin_worker(
            job_id=job_id,
            request=request,
            plan_payload=plan.to_record(),
            runtime_mode="workflow",
            lane_id="enrichment_specialist",
            worker_key="harvest_profile_batch::chatgpt-tail",
            stage="enriching",
            span_name="harvest_profile_batch:chatgpt-tail",
            budget_payload={"requested_url_count": 2},
            input_payload={"profile_urls": [fetched_url, queued_url]},
            metadata={"recovery_kind": "harvest_profile_batch", "profile_urls": [fetched_url, queued_url]},
            handoff_from_lane="search_planner",
        )
        self.store.repos.linkedin_profile_registry.mark_fetched(fetched_url, raw_path="/tmp/openai-chatgpt-fetched.json")
        self.store.repos.linkedin_profile_registry.mark_queued(queued_url)

        progress = self.orchestrator.get_job_progress(job_id)

        assert progress is not None
        contract = dict(progress["execution_phase_contract"])
        self.assertEqual(contract["active_phase_id"], "linkedin_acquisition")
        self.assertEqual(contract["active_stage_id"], "linkedin_stage_1")
        self.assertEqual(contract["active_phase_label"], "LinkedIn Stage 1")
        self.assertTrue(contract["profile_work_pending"])
        self.assertFalse(contract["public_web_stage_applicable"])
        self.assertNotEqual(
            dict(contract["stage_title_overrides"])["public_web_stage_2"],
            "Public Web Stage 2",
        )

