    def test_asset_population_summary_cache_refreshes_after_artifact_rebuild(self) -> None:
        snapshot_id = "20260427T010203"
        snapshot_dir = self._write_materialized_snapshot_view(
            target_company="Wispr Flow",
            snapshot_id=snapshot_id,
            candidates=[
                {
                    "candidate_id": "cand_current_1",
                    "display_name": "Current One",
                    "name_en": "Current One",
                    "target_company": "Wispr Flow",
                    "organization": "Wispr Flow",
                    "employment_status": "current",
                    "linkedin_url": "https://www.linkedin.com/in/current-one/",
                }
            ],
        )
        artifact_summary_path = snapshot_dir / "normalized_artifacts" / "artifact_summary.json"

        def _write_profile_progress(candidate_count: int) -> None:
            summary = json.loads(artifact_summary_path.read_text(encoding="utf-8"))
            summary.update(
                {
                    "candidate_count": candidate_count,
                    "profile_detail_count": candidate_count,
                    "profile_completion_backlog_count": 0,
                    "missing_linkedin_count": 0,
                }
            )
            artifact_summary_path.write_text(json.dumps(summary, ensure_ascii=False, indent=2), encoding="utf-8")
            os.utime(artifact_summary_path, None)
            os.utime(snapshot_dir / "normalized_artifacts" / "manifest.json", None)

        _write_profile_progress(1)
        job_id = "job_asset_population_cache_refresh"
        self.store.save_job(
            job_id=job_id,
            job_type="workflow",
            status="completed",
            stage="completed",
            request_payload={
                "raw_user_request": "帮我找 Wispr Flow 的全部成员",
                "query": "帮我找 Wispr Flow 的全部成员",
                "target_company": "Wispr Flow",
                "target_scope": "full_company_asset",
            },
            plan_payload={},
            summary_payload={
                "candidate_source": {
                    "source_kind": "company_snapshot",
                    "snapshot_id": snapshot_id,
                    "asset_view": "canonical_merged",
                    "candidate_count": 1,
                }
            },
        )

        first_page = self.orchestrator.get_job_candidate_page(job_id, offset=0, limit=1, lightweight=True)
        assert first_page is not None
        self.assertEqual(first_page["total_candidates"], 1)
        self.assertEqual(first_page["profile_fetch_progress"]["total_url_count"], 1)

        self._write_materialized_snapshot_view(
            target_company="Wispr Flow",
            snapshot_id=snapshot_id,
            candidates=[
                {
                    "candidate_id": "cand_current_1",
                    "display_name": "Current One",
                    "name_en": "Current One",
                    "target_company": "Wispr Flow",
                    "organization": "Wispr Flow",
                    "employment_status": "current",
                    "linkedin_url": "https://www.linkedin.com/in/current-one/",
                },
                {
                    "candidate_id": "cand_former_1",
                    "display_name": "Former One",
                    "name_en": "Former One",
                    "target_company": "Wispr Flow",
                    "organization": "Wispr Flow",
                    "employment_status": "former",
                    "linkedin_url": "https://www.linkedin.com/in/former-one/",
                },
            ],
        )
        _write_profile_progress(2)

        refreshed_page = self.orchestrator.get_job_candidate_page(job_id, offset=0, limit=1, lightweight=True)
        assert refreshed_page is not None
        self.assertEqual(refreshed_page["total_candidates"], 2)
        self.assertEqual(refreshed_page["profile_fetch_progress"]["total_url_count"], 2)
        self.assertEqual(refreshed_page["profile_fetch_progress"]["fetched_url_count"], 2)

