    def test_job_api_is_summary_only_by_default_and_detail_is_opt_in(self) -> None:
        job_id = "job_api_summary_default"
        self.store.save_job(
            job_id=job_id,
            job_type="workflow",
            status="completed",
            stage="completed",
            request_payload={
                "raw_user_request": "帮我找 OpenAI 做 Coding 的人",
                "query": "OpenAI Coding",
                "target_company": "OpenAI",
                "target_scope": "full_company_asset",
            },
            plan_payload={"asset_reuse_plan": {"baseline_reuse_available": True}},
            summary_payload={
                "message": "Local asset population is ready.",
                "candidate_count": 26,
                "candidate_ids": [f"cand_{index}" for index in range(1000)],
                "raw_profile_payload": {"profiles": [{"name": "too large"} for _ in range(1000)]},
            },
        )
        self.store.append_job_event(
            job_id,
            "runtime_control",
            "completed",
            "Background runner finished.",
            {
                "detail": "Background runner finished.",
                "candidate_ids": [f"cand_{index}" for index in range(1000)],
                "raw_profile_payload": {"profiles": [{"name": "too large"} for _ in range(1000)]},
            },
        )

        server = create_server(self.orchestrator, host="127.0.0.1", port=0)
        thread = threading.Thread(target=server.serve_forever, daemon=True)
        thread.start()
        host, port = server.server_address
        opener = urllib_request.build_opener(urllib_request.ProxyHandler({}))
        try:
            with opener.open(f"http://{host}:{port}/api/jobs/{job_id}") as response:
                summary_payload = json.loads(response.read().decode("utf-8"))
            with opener.open(f"http://{host}:{port}/api/jobs/{job_id}?include_details=1") as response:
                detail_payload = json.loads(response.read().decode("utf-8"))
        finally:
            server.shutdown()
            server.server_close()
            thread.join(timeout=5)

        self.assertEqual(summary_payload["job_id"], job_id)
        self.assertEqual(summary_payload["summary"]["candidate_count"], 26)
        self.assertEqual(summary_payload["summary"]["candidate_id_count"], 1000)
        self.assertNotIn("candidate_ids", summary_payload["summary"])
        self.assertNotIn("raw_profile_payload", summary_payload["summary"])
        self.assertEqual(summary_payload["request"]["target_company"], "OpenAI")
        self.assertNotIn("events", summary_payload)
        self.assertNotIn("intent_rewrite", summary_payload)
        self.assertEqual(len(detail_payload["events"]), 1)
        self.assertEqual(detail_payload["events"][0]["payload"]["candidate_id_count"], 1000)
        self.assertNotIn("candidate_ids", detail_payload["events"][0]["payload"])
        self.assertNotIn("raw_profile_payload", detail_payload["events"][0]["payload"])
        self.assertIn("intent_rewrite", detail_payload)

    def test_job_api_compact_details_preserve_remote_provider_metrics(self) -> None:
        job_id = "job_api_remote_provider_metrics"
        self.store.save_job(
            job_id=job_id,
            job_type="workflow",
            status="completed",
            stage="completed",
            request_payload={"target_company": "Google"},
            plan_payload={},
            summary_payload={},
        )
        self.store.append_job_event(
            job_id,
            "remote_provider_event",
            "received",
            "Remote provider terminal event received.",
            {
                "event": {
                    "provider": "apify",
                    "event_type": "ACTOR.RUN.SUCCEEDED",
                    "run_id": "run_compact_metrics",
                    "dataset_id": "dataset_compact_metrics",
                    "remote_completed_at": "2026-05-23T07:32:59+00:00",
                },
                "target_worker_ids": [901],
                "released_worker_ids": [901],
                "event_metrics": {
                    "source": "local_provider_event_watcher",
                    "remote_completed_at": "2026-05-23T07:32:59+00:00",
                    "local_event_seen_at": "2026-05-23T07:33:02+00:00",
                    "remote_to_local_event_lag_ms": 2037,
                    "actor_run_duration_ms": 240000,
                },
                "candidate_ids": [f"cand_{index}" for index in range(1000)],
            },
        )

        server = create_server(self.orchestrator, host="127.0.0.1", port=0)
        thread = threading.Thread(target=server.serve_forever, daemon=True)
        thread.start()
        host, port = server.server_address
        opener = urllib_request.build_opener(urllib_request.ProxyHandler({}))
        try:
            with opener.open(f"http://{host}:{port}/api/jobs/{job_id}?include_details=1") as response:
                detail_payload = json.loads(response.read().decode("utf-8"))
        finally:
            server.shutdown()
            server.server_close()
            thread.join(timeout=5)

        event_payload = dict(detail_payload["events"][0]["payload"])
        self.assertEqual(event_payload["target_worker_ids"], [901])
        self.assertEqual(event_payload["event"]["run_id"], "run_compact_metrics")
        self.assertEqual(event_payload["event"]["dataset_id"], "dataset_compact_metrics")
        self.assertEqual(event_payload["event_metrics"]["source"], "local_provider_event_watcher")
        self.assertEqual(event_payload["event_metrics"]["remote_to_local_event_lag_ms"], 2037)
        self.assertEqual(event_payload["event_metrics"]["actor_run_duration_ms"], 240000)
        self.assertEqual(event_payload["candidate_id_count"], 1000)
        self.assertNotIn("candidate_ids", event_payload)

