    def test_job_scoped_recovery_tick_does_not_stop_service_while_workflow_open(self) -> None:
        job_id = "job_recovery_keeps_workflow_owner_alive"
        self.store.save_job(
            job_id=job_id,
            job_type="workflow",
            status="running",
            stage="acquiring",
            request_payload={
                "raw_user_request": "帮我找Google里做vision-language方向的人",
                "query": "Google vision-language",
                "target_company": "Google",
            },
            plan_payload={},
            summary_payload={"message": "Profile work drained; workflow still needs final resume."},
        )

        class _FakeService:
            stopped = False

            def request_stop(self) -> None:
                self.stopped = True

        fake_service = _FakeService()
        with mock.patch.object(
            self.orchestrator,
            "run_worker_recovery_once",
            return_value={"status": "completed", "daemon": {"claimed_count": 0, "executed_count": 0}},
        ):
            summary = self.orchestrator._run_job_scoped_recovery_tick(  # noqa: SLF001
                job_id=job_id,
                daemon_payload={"job_id": job_id},
                service_ref={"service": fake_service},
            )

        self.assertFalse(fake_service.stopped)
        self.assertEqual(summary["job_recovery_open_work"]["workflow_open_count"], 1)
        self.assertEqual(summary["job_recovery_open_work"]["daemon_owned_open_work_count"], 0)

