    def test_get_job_progress_does_not_promote_results_ready_job_with_active_workers(self) -> None:
        job_id = "job_progress_promotion_blocked_by_active_workers"
        request_payload = {
            "raw_user_request": "帮我找OpenAI做Agent方向的人",
            "query": "帮我找OpenAI做Agent方向的人",
            "target_company": "OpenAI",
        }
        self.store.save_job(
            job_id=job_id,
            job_type="workflow",
            status="blocked",
            stage="acquiring",
            request_payload=request_payload,
            plan_payload={},
            summary_payload={
                "message": "Waiting on remote Harvest profile workers.",
                "blocked_task": "acquire-full-roster",
            },
        )
        self.store.replace_job_results(
            job_id,
            [
                {
                    "candidate_id": "cand_openai_agent_worker_tail",
                    "rank": 1,
                    "score": 0.91,
                    "semantic_score": 0.0,
                    "confidence_label": "high",
                    "confidence_score": 0.91,
                    "confidence_reason": "stage2 final ready",
                    "explanation": "Recovered from completed stage 2 final results.",
                    "matched_fields": ["work_history"],
                }
            ],
        )
        request = JobRequest.from_payload(request_payload)
        worker = self.orchestrator.agent_runtime.begin_worker(
            job_id=job_id,
            request=request,
            plan_payload={},
            runtime_mode="workflow",
            lane_id="acquisition_specialist",
            worker_key="harvest_profile_batch::active-tail",
            stage="acquiring",
            span_name="harvest_profile_batch:active-tail",
            budget_payload={"requested_url_count": 25},
            input_payload={"profile_urls": ["https://www.linkedin.com/in/openai-agent-active-tail/"]},
            metadata={"recovery_kind": "harvest_profile_batch"},
            handoff_from_lane="planning",
        )
        self.orchestrator.agent_runtime.checkpoint_worker(
            worker,
            checkpoint_payload={"stage": "waiting_remote_harvest"},
            output_payload={"summary": {"status": "submitted"}},
            status="waiting_remote_harvest",
        )

        with (
            mock.patch.object(
                self.orchestrator,
                "_load_workflow_stage_summaries",
                return_value={"summaries": {"stage_2_final": {"status": "completed"}}},
            ),
            mock.patch.object(self.orchestrator, "_maybe_auto_recover_workflow_on_progress", return_value={}),
        ):
            progress = self.orchestrator.get_job_progress(job_id)

        assert progress is not None
        self.assertEqual(progress["status"], "blocked")
        self.assertEqual(progress["stage"], "acquiring")
        refreshed_job = self.store.get_job(job_id)
        assert refreshed_job is not None
        self.assertEqual(refreshed_job["status"], "blocked")
        self.assertEqual(refreshed_job["stage"], "acquiring")

