    @unittest.skip("legacy target-candidate Public Web execution is permanently retired; CRM Public Web owns e2e coverage")
    @mock.patch.dict(os.environ, {"SOURCING_ALLOW_LEGACY_TARGET_PUBLIC_WEB_ENDPOINTS": "1"}, clear=False)
    def test_target_candidate_public_web_cancel_and_retry_are_durable_run_actions(self) -> None:
        record = self.store.upsert_target_candidate(
            {
                "record_id": "target-public-web-control-1",
                "candidate_id": "cand-public-web-control-1",
                "candidate_name": "Alice Control",
                "current_company": "Example AI",
                "linkedin_url": "https://www.linkedin.com/in/alice-control/",
            }
        )
        server = create_server(self.orchestrator, host="127.0.0.1", port=0)
        thread = threading.Thread(target=server.serve_forever, daemon=True)
        thread.start()
        host, port = server.server_address
        opener = urllib_request.build_opener(urllib_request.ProxyHandler({}))
        try:
            start_request = urllib_request.Request(
                f"http://{host}:{port}/api/target-candidates/public-web-search",
                data=json.dumps(
                    {
                        "record_ids": [record["id"]],
                        "options": {
                            "max_queries_per_candidate": 2,
                            "fetch_content": False,
                            "ai_extraction": "off",
                        },
                    }
                ).encode("utf-8"),
                headers={"Content-Type": "application/json"},
                method="POST",
            )
            with opener.open(start_request) as response:
                queued = json.loads(response.read().decode("utf-8"))
            run_id = queued["runs"][0]["run_id"]

            cancel_request = urllib_request.Request(
                f"http://{host}:{port}/api/target-candidates/public-web-search/cancel",
                data=json.dumps({"run_ids": [run_id], "reason": "operator_changed_scope"}).encode("utf-8"),
                headers={"Content-Type": "application/json"},
                method="POST",
            )
            with opener.open(cancel_request) as response:
                cancelled = json.loads(response.read().decode("utf-8"))

            retry_request = urllib_request.Request(
                f"http://{host}:{port}/api/target-candidates/public-web-search/retry",
                data=json.dumps({"run_ids": [run_id], "reason": "retry_after_cancel"}).encode("utf-8"),
                headers={"Content-Type": "application/json"},
                method="POST",
            )
            with opener.open(retry_request) as response:
                retried = json.loads(response.read().decode("utf-8"))
        finally:
            server.shutdown()
            server.server_close()
            thread.join(timeout=5)

        self.assertEqual(cancelled["status"], "cancelled")
        self.assertEqual(cancelled["runs"][0]["status"], "cancelled")
        self.assertEqual(cancelled["worker_summary"]["interrupted_worker_count"], 1)
        self.assertEqual(retried["status"], "retried")
        self.assertEqual(retried["source_runs"][0]["run_id"], run_id)
        self.assertNotEqual(retried["runs"][0]["run_id"], run_id)
        self.assertEqual(retried["runs"][0]["status"], "queued")
        old_run = self.store.get_target_candidate_public_web_run(run_id=run_id)
        new_run = self.store.get_target_candidate_public_web_run(run_id=retried["runs"][0]["run_id"])
        self.assertEqual(old_run["status"], "cancelled")
        self.assertEqual(new_run["record_id"], record["id"])
        old_workers = self.store.list_agent_workers(job_id=queued["job"]["job_id"])
        new_workers = self.store.list_agent_workers(job_id=retried["job"]["job_id"])
        self.assertEqual(old_workers[0]["status"], "cancelled")
        self.assertEqual(new_workers[0]["wait_stage"], "waiting_remote_search")

