    @mock.patch.dict(os.environ, {"SOURCING_ALLOW_LEGACY_TARGET_PUBLIC_WEB_ENDPOINTS": "1"}, clear=False)
    def test_target_candidate_public_web_service_e2e_runs_to_detail_and_export_contract(self) -> None:
        record = self.store.upsert_target_candidate(
            {
                "record_id": "target-public-web-service-e2e-1",
                "candidate_id": "cand-public-web-service-e2e-1",
                "candidate_name": "Alice Service E2E",
                "current_company": "Example AI",
                "headline": "Research Engineer",
                "linkedin_url": "https://www.linkedin.com/in/alice-service-e2e/",
            }
        )
        start = self.orchestrator.start_target_candidate_public_web_search(
            {
                "record_ids": [record["id"]],
                "options": {
                    "max_queries_per_candidate": 1,
                    "fetch_content": False,
                    "ai_extraction": "off",
                },
            }
        )
        self.assertEqual(start["status"], "queued")
        run_id = start["runs"][0]["run_id"]
        provider = _PublicWebServiceE2EProvider()
        observed_statuses: list[str] = []

        for _ in range(8):
            result = execute_target_candidate_public_web_run_once(
                store=self.store,
                search_provider=provider,
                model_client=None,
                runtime_dir=self.tempdir.name,
                run_id=run_id,
            )
            observed_statuses.append(str(result.get("run_status") or ""))
            if result.get("worker_status") == "completed":
                break

        self.assertEqual(
            observed_statuses,
            [
                "searching",
                "entry_links_ready",
                "documents_fetched",
                "adjudication_completed",
                "analysis_completed",
                "completed",
            ],
        )
        self.assertEqual(provider.submit_calls, 1)
        self.assertEqual(provider.poll_calls, 2)
        self.assertEqual(provider.fetch_calls, 1)

        completed = self.store.get_target_candidate_public_web_run(run_id=run_id)
        self.assertEqual(completed["status"], "completed")
        metrics = dict(dict(completed.get("summary") or {}).get("phase_metrics") or {})
        self.assertEqual(metrics["pending_task_count"], 0)
        self.assertEqual(metrics["fetched_task_count"], 1)
        self.assertIn("search_submit_duration_ms", metrics)
        self.assertIn("search_poll_duration_ms", metrics)
        self.assertIn("search_fetch_duration_ms", metrics)
        self.assertIn("adjudication_duration_ms", metrics)
        self.assertIn("analysis_duration_ms", metrics)
        self.assertIn("signal_materialization_duration_ms", metrics)
        self.assertEqual(metrics["signal_materialized_count"], 1)

        analysis_checkpoint = dict(completed.get("analysis_checkpoint") or {})
        document_fetch_payload_path = Path(str(analysis_checkpoint["document_fetch_payload_path"]))
        adjudication_payload_path = Path(str(analysis_checkpoint["adjudication_payload_path"]))
        artifact_root = Path(str(dict(completed.get("summary") or {})["artifact_root"]))
        self.assertEqual(document_fetch_payload_path.parent, artifact_root)
        self.assertEqual(adjudication_payload_path.parent, artifact_root)
        self.assertTrue(document_fetch_payload_path.exists())
        self.assertTrue(adjudication_payload_path.exists())
        self.assertTrue((artifact_root / "signals.json").exists())
        self.assertTrue((artifact_root / "candidate_summary.json").exists())
        signals = self.store.list_person_public_web_signals(run_id=run_id)
        self.assertEqual(len(signals), 1)
        self.assertEqual(signals[0]["source_url"], "https://github.com/alice-service-e2e")

        detail = self.orchestrator.get_target_candidate_public_web_search_detail(record["id"])
        self.assertEqual(detail["status"], "ok")
        self.assertEqual(detail["latest_run"]["run_id"], run_id)
        self.assertEqual(len(detail["signals"]), 1)
        detail_text = json.dumps(detail, ensure_ascii=False)
        self.assertNotIn("artifact_root", detail_text)
        self.assertNotIn("document_fetch_payload_path", detail_text)
        self.assertNotIn("adjudication_payload_path", detail_text)
        self.assertNotIn("raw_payload", detail_text)

        promoted = self.orchestrator.promote_target_candidate_public_web_signal(
            record["id"],
            {
                "signal_id": signals[0]["signal_id"],
                "action": "promote",
                "operator": "service-e2e",
                "allow_unpublishable": True,
                "override_reason": "Service-level E2E confirms this model-safe link for export.",
            },
        )
        self.assertEqual(promoted["status"], "promoted")
        publishable_export = self.orchestrator.export_target_candidate_public_web_archive(
            {"record_ids": [record["id"]], "mode": "promoted_and_publishable"}
        )
        self.assertEqual(publishable_export["status"], "ok")
        self.assertEqual(publishable_export["exported_record_count"], 1)
        self.assertEqual(publishable_export["exported_signal_count"], 1)
        with zipfile.ZipFile(io.BytesIO(publishable_export["body"]), "r") as archive:
            names = set(archive.namelist())
            summary_name = next(name for name in names if name.endswith("/public_web_summary.csv"))
            manifest_name = next(name for name in names if name.endswith("/public_web_manifest.json"))
            summary_csv = archive.read(summary_name).decode("utf-8-sig")
            manifest = json.loads(archive.read(manifest_name).decode("utf-8"))
        self.assertIn("https://github.com/alice-service-e2e", summary_csv)
        self.assertEqual(manifest["exported_record_count"], 1)
        self.assertEqual(manifest["records"][0]["export_record_status"], "exported")

        export = self.orchestrator.export_target_candidate_public_web_archive({"record_ids": [record["id"]]})
        self.assertEqual(export["status"], "ok")
        with zipfile.ZipFile(io.BytesIO(export["body"]), "r") as archive:
            archive_text = "\n".join(
                archive.read(name).decode("utf-8", errors="ignore")
                for name in archive.namelist()
                if name.endswith((".csv", ".json"))
            )
        self.assertIn("https://github.com/alice-service-e2e", archive_text)
        self.assertIn("service-e2e", archive_text)
        self.assertNotIn("artifact_root", archive_text)
        self.assertNotIn("document_fetch_payload_path", archive_text)
        self.assertNotIn("adjudication_payload_path", archive_text)
        self.assertNotIn("raw_payload", archive_text)

    def test_lifecycle_consistent_across_dashboard_progress_and_candidate_page_for_openai_infra_shape(self) -> None:
        """Anchor regression for hosted OpenAI Infra job c5248ea4b3b4.

        Reproduces the failure shape: terminal workflow, baseline-serving result view,
        delta_profile_required/fetched=89/89, but materialized=19, expected=1200.
        Asserts every public API path (/dashboard, /candidates, /progress) reports a
        consistent lifecycle row. Today they each rebuild from different inputs and
        disagree, which is exactly what the canonical job_result_lifecycle slice will
        retire (see docs/JOB_RESULT_LIFECYCLE_DESIGN.md).
        """
        baseline_snapshot_id = "20260430T130836"
        current_snapshot_id = "20260430T155907"
        baseline_candidates = [
            {"candidate_id": f"infra_baseline_{i}", "display_name": f"Infra Baseline {i}"}
            for i in range(1, 6)
        ]
        self._write_candidate_documents_snapshot(
            target_company="OpenAI",
            snapshot_id=baseline_snapshot_id,
            candidates=baseline_candidates,
        )
        baseline_source_path = (
            Path(self.tempdir.name)
            / "company_assets"
            / normalize_company_key("OpenAI")
            / baseline_snapshot_id
            / "candidate_documents.json"
        )

        job_id = "c5248ea4b3b4"
        request_payload = {
            "raw_user_request": "帮我找OpenAI做Infra方向的人",
            "target_company": "OpenAI",
            "keywords": ["Infra"],
            "employment_statuses": ["current", "former"],
            "execution_preferences": {"delta_baseline_snapshot_id": baseline_snapshot_id},
        }
        self.store.save_job(
            job_id=job_id,
            job_type="workflow",
            status="completed",
            stage="completed",
            request_payload=request_payload,
            plan_payload={
                "asset_reuse_plan": {
                    "baseline_reuse_available": True,
                    "requires_delta_acquisition": True,
                    "planner_mode": "baseline_reuse_with_delta",
                    "baseline_snapshot_id": baseline_snapshot_id,
                    "baseline_candidate_count": 1200,
                }
            },
            summary_payload={
                "candidate_source": {
                    "source_kind": "company_snapshot",
                    "target_company": "OpenAI",
                    "snapshot_id": baseline_snapshot_id,
                    "asset_view": "canonical_merged",
                    "source_path": str(baseline_source_path),
                    "candidate_count": 1200,
                    "baseline_selection_explanation": {
                        "baseline_snapshot_id": baseline_snapshot_id,
                        "baseline_candidate_count": 1200,
                        "requires_delta_acquisition": True,
                    },
                },
                "background_snapshot_materialization": {
                    "status": "deferred",
                    "snapshot_id": current_snapshot_id,
                },
            },
        )
        # Baseline-serving result view persisted; never repointed to the current snapshot.
        self.store.upsert_job_result_view(
            job_id=job_id,
            target_company="OpenAI",
            source_kind="company_snapshot",
            view_kind="asset_population",
            snapshot_id=baseline_snapshot_id,
            asset_view="canonical_merged",
            source_path=str(baseline_source_path),
            authoritative_snapshot_id=baseline_snapshot_id,
            summary={"candidate_count": 1200, "default_results_mode": "asset_population"},
            metadata={
                "result_view_lifecycle": {
                    "state": "baseline_serving",
                    "baseline_snapshot_id": baseline_snapshot_id,
                    "current_snapshot_id": current_snapshot_id,
                    "served_snapshot_id": baseline_snapshot_id,
                    "baseline_candidate_count": 1200,
                    "served_candidate_count": 1200,
                    "expected_candidate_count": 1200,
                    "delta_profile_required_count": 89,
                    "delta_profile_fetched_count": 89,
                    # Materialization stalled at 19/89 — board lags despite "completed" job.
                    "delta_profile_materialized_count": 19,
                },
            },
        )
        self._seed_canonical_lifecycle_for_test(job_id)

        dashboard = self.orchestrator.get_job_dashboard(job_id)
        page = self.orchestrator.get_job_candidate_page(job_id, offset=0, limit=10, lightweight=True)
        progress = self.orchestrator.get_job_progress(job_id)
        assert dashboard is not None
        assert page is not None
        assert progress is not None

        dashboard_lifecycle = dict(dashboard.get("result_view_lifecycle") or {})
        page_lifecycle = dict(page.get("result_view_lifecycle") or {})
        progress_lifecycle = dict(progress.get("result_view_lifecycle") or {})

        # Architecture invariant: all three public readers must observe the same
        # lifecycle row at the same instant. Today each rebuilds from different
        # inputs (candidate_source / asset_population / result_view / job.summary)
        # so they disagree on at least one of these fields under the Infra shape.
        canonical_fields = (
            "state",
            "baseline_snapshot_id",
            "current_snapshot_id",
            "served_snapshot_id",
            "baseline_candidate_count",
            "served_candidate_count",
            "expected_candidate_count",
            "delta_profile_required_count",
            "delta_profile_fetched_count",
            "delta_profile_materialized_count",
        )
        for field in canonical_fields:
            self.assertEqual(
                dashboard_lifecycle.get(field),
                progress_lifecycle.get(field),
                msg=f"/dashboard and /progress disagree on lifecycle field {field!r}",
            )
            self.assertEqual(
                dashboard_lifecycle.get(field),
                page_lifecycle.get(field),
                msg=f"/dashboard and /candidates disagree on lifecycle field {field!r}",
            )

        # Architecture invariant: a terminal workflow cannot expose stable `results`
        # while serving a stale baseline-only board with delta materialization
        # incomplete. Either the lifecycle has repointed to the current snapshot,
        # or it explicitly reports a post-result materialization phase that the
        # candidate page can serve without synchronous rebuild.
        self.assertEqual(progress.get("status"), "completed")
        terminal_with_stale_baseline = (
            dashboard_lifecycle.get("served_snapshot_id") == baseline_snapshot_id
            and int(dashboard_lifecycle.get("delta_profile_required_count") or 0) > 0
            and int(dashboard_lifecycle.get("delta_profile_materialized_count") or 0)
            < int(dashboard_lifecycle.get("delta_profile_required_count") or 0)
        )
        if terminal_with_stale_baseline:
            self.assertIn(
                str(dashboard_lifecycle.get("state") or ""),
                {"current_snapshot_materializing", "post_result_layering", "delta_applying"},
                msg=(
                    "Terminal workflow exposes stable `results` while serving stale baseline "
                    "with materialization=19/89 — lifecycle must report an explicit post-result "
                    "materialization phase, not `baseline_serving`."
                ),
            )

        # Anchor invariant: the canonical `job_result_lifecycle` row is prepared
        # by explicit event-time/backfill ownership before public reads. Public
        # reads must not rebuild lifecycle from scratch on every request.
        persisted_row = self.store.get_job_result_lifecycle(job_id)
        assert persisted_row is not None, "canonical lifecycle row must be persisted"
        self.assertEqual(persisted_row["baseline_snapshot_id"], baseline_snapshot_id)
        self.assertEqual(persisted_row["served_snapshot_id"], baseline_snapshot_id)
        self.assertEqual(persisted_row["source_validation_status"], "validated")

    def test_job_result_lifecycle_writer_initialize_persists_planning_row_without_public_read(self) -> None:
        """The workflow-create writer must persist a `job_result_lifecycle`
        row before any public API is called. Public reads then use the fast
        path (validated persisted row) and do not need to re-project."""

        request = JobRequest.from_payload(
            {
                "raw_user_request": "帮我找OpenAI做Agent方向的人",
                "target_company": "OpenAI",
                "keywords": ["Agent"],
            }
        )
        plan = hydrate_sourcing_plan(self.orchestrator.plan_workflow(request.to_record())["plan"])

        row = self.orchestrator.initialize_job_result_lifecycle(
            job_id="job_lifecycle_init_writer",
            request=request,
            plan=plan,
            baseline_snapshot_id="20260420T120000",
            baseline_candidate_count=10,
            workflow_kind="linkedin_stage_1",
        )

        self.assertEqual(row["job_id"], "job_lifecycle_init_writer")
        self.assertEqual(row["phase"], "planning")
        self.assertEqual(row["baseline_snapshot_id"], "20260420T120000")
        self.assertEqual(row["baseline_candidate_count"], 10)
        self.assertEqual(row["expected_candidate_count"], 10)
        self.assertEqual(row["source_validation_status"], "validated")

        persisted = self.store.get_job_result_lifecycle("job_lifecycle_init_writer")
        assert persisted is not None
        self.assertEqual(persisted["phase"], "planning")
        self.assertEqual(persisted["baseline_candidate_count"], 10)

    def test_job_result_lifecycle_writer_publish_baseline_persists_row_before_public_read(self) -> None:
        """`_create_workflow_job` must persist a `baseline_serving` row through
        the lifecycle writer before any public API is touched."""

        baseline_snapshot_id = "20260420T120000"
        self._write_materialized_snapshot_view(
            target_company="OpenAI",
            snapshot_id=baseline_snapshot_id,
            candidates=[
                {"candidate_id": "baseline_member_1", "display_name": "Baseline One"},
                {"candidate_id": "baseline_member_2", "display_name": "Baseline Two"},
            ],
        )
        request = JobRequest.from_payload(
            {
                "raw_user_request": "帮我找OpenAI做Agent方向的人",
                "target_company": "OpenAI",
                "keywords": ["Agent"],
                "execution_preferences": {"delta_baseline_snapshot_id": baseline_snapshot_id},
            }
        )
        plan = hydrate_sourcing_plan(self.orchestrator.plan_workflow(request.to_record())["plan"])
        plan.asset_reuse_plan = {
            "baseline_reuse_available": True,
            "requires_delta_acquisition": True,
            "planner_mode": "baseline_reuse_with_delta",
            "baseline_snapshot_id": baseline_snapshot_id,
            "baseline_candidate_count": 2,
        }

        job_id = self.orchestrator._create_workflow_job(request, plan)  # noqa: SLF001

        row = self.store.get_job_result_lifecycle(job_id)
        assert row is not None, "lifecycle row must be persisted at workflow create / baseline publication"
        self.assertEqual(row["phase"], "baseline_serving")
        self.assertEqual(row["baseline_snapshot_id"], baseline_snapshot_id)
        self.assertEqual(row["served_snapshot_id"], baseline_snapshot_id)
        self.assertEqual(row["baseline_candidate_count"], 2)
        self.assertEqual(row["served_candidate_count"], 2)
        self.assertEqual(row["source_validation_status"], "validated")

        # Public reads use the validated fast path; they must not mutate the
        # row's canonical fields.
        before = dict(self.store.get_job_result_lifecycle(job_id) or {})
        dashboard = self.orchestrator.get_job_dashboard(job_id)
        after = dict(self.store.get_job_result_lifecycle(job_id) or {})
        assert dashboard is not None
        for field in (
            "phase",
            "state",
            "baseline_snapshot_id",
            "served_snapshot_id",
            "baseline_candidate_count",
            "served_candidate_count",
        ):
            self.assertEqual(before.get(field), after.get(field), msg=f"validated read mutated {field!r}")

        lifecycle = dict(dashboard["result_view_lifecycle"])
        self.assertEqual(lifecycle["state"], "baseline_serving")
        self.assertEqual(lifecycle["served_candidate_count"], 2)

