        self.assertEqual(patch["overlay_write_mode"], "current_snapshot_serving_reuse")
        card_summary = dict(patch["card_materialization_summary"])
        self.assertEqual(card_summary["summary_source"], "job_result_lifecycle_projection_v1")
        self.assertEqual(card_summary["candidate_count"], 8831)
        self.assertEqual(card_summary["display_ready_candidate_count"], 8791)
        stored_patch = self.store.list_job_board_visible_patches(
            job_id=job_id,
            snapshot_id=current_snapshot_id,
        )[-1]
        self.assertEqual(stored_patch["patch_phase"], "board_visible_delta_already_served")
        stored_metadata = dict(stored_patch["metadata"])
        self.assertEqual(
            dict(stored_metadata["result_view_metadata_mirror"])["overlay_write_mode"],
            "current_snapshot_serving_reuse",
        )

