    def test_board_visible_delta_chunk_size_keeps_provider_batch_sized_wave_together(self) -> None:
        with mock.patch.dict(
            os.environ,
            {
                "BOARD_VISIBLE_DELTA_APPLY_CHUNK_SIZE": "256",
                "BOARD_VISIBLE_DELTA_APPLY_TARGET_CHUNK_COUNT": "8",
                "BOARD_VISIBLE_DELTA_APPLY_MAX_CHUNK_SIZE": "512",
            },
            clear=False,
        ):
            self.assertEqual(
                self.orchestrator._resolve_board_visible_delta_apply_chunk_size(248),  # noqa: SLF001
                256,
            )
            self.assertEqual(
                self.orchestrator._resolve_board_visible_delta_apply_chunk_size(600),  # noqa: SLF001
                256,
            )
            self.assertEqual(
                self.orchestrator._resolve_board_visible_delta_apply_chunk_size(2384),  # noqa: SLF001
                298,
            )

        with mock.patch.dict(
            os.environ,
            {
                "BOARD_VISIBLE_DELTA_APPLY_CHUNK_SIZE": "2",
                "BOARD_VISIBLE_DELTA_APPLY_TARGET_CHUNK_COUNT": "8",
                "BOARD_VISIBLE_DELTA_APPLY_MAX_CHUNK_SIZE": "512",
            },
            clear=False,
        ):
            self.assertEqual(
                self.orchestrator._resolve_board_visible_delta_apply_chunk_size(5),  # noqa: SLF001
                2,
            )

