    def test_board_runtime_state_current_snapshot_serving_does_not_infer_profiles_from_row_shell(self) -> None:
        job_id = "job_no_baseline_current_serving_patch_stale"
        snapshot_id = "20260513T193651"
        self.store.upsert_job_board_visible_patch(
            patch_id=f"{job_id}|{snapshot_id}|partial",
            job_id=job_id,
            target_company="OpenAI",
            snapshot_id=snapshot_id,
            baseline_snapshot_id="",
            candidate_ids=[f"openai_agent_{index}" for index in range(112)],
            cumulative_candidate_ids=[f"openai_agent_{index}" for index in range(112)],
            candidate_count=112,
            cumulative_candidate_count=112,
            served_candidate_count=112,
            serving_projection_phase="partial_current_snapshot_overlay",
            sequence_index=2,
            metadata={
                "card_materialization_summary": {
                    "quality_fields_available": True,
                    "candidate_count": 112,
                    "display_ready_candidate_count": 112,
                    "profile_detail_candidate_count": 112,
                    "explicit_profile_capture_candidate_count": 112,
                }
            },
        )

        board_state = self.orchestrator._build_board_runtime_state(  # noqa: SLF001
            job_id=job_id,
            job={"job_id": job_id, "status": "completed"},
            result_mode="asset_population",
            result_view_lifecycle={
                "state": "current_snapshot_serving",
                "serving_projection_phase": "current_snapshot_serving",
                "baseline_snapshot_id": "",
                "current_snapshot_id": snapshot_id,
                "served_snapshot_id": snapshot_id,
                "baseline_candidate_count": 0,
                "served_candidate_count": 297,
                "expected_candidate_count": 297,
                "delta_profile_progress_applicable": False,
                "stage1_current_search_returned_count": 223,
                "stage1_former_search_returned_count": 74,
                "stage1_deduped_candidate_count": 297,
                "stage1_deduped_profile_url_count": 297,
                "stage1_profile_fetch_required_count": 297,
                "stage1_profile_fetched_count": 186,
                "metadata": {"delta_profile_denominator_promoted": True},
            },
            asset_population={
                "candidate_count": 297,
                "snapshot_id": snapshot_id,
                "card_materialization_summary": {
                    "quality_fields_available": True,
                    "candidate_count": 297,
                    "display_ready_candidate_count": 112,
                    "profile_detail_candidate_count": 112,
                    "preview_candidate_count": 185,
                    "needs_profile_completion_candidate_count": 185,
                },
            },
            linkedin_stage_1_progress={
                "deduped_candidate_count": 297,
                "profile_fetch_required_count": 297,
                "profile_fetched_count": 186,
            },
        )

        self.assertEqual(board_state["publication_status"], "complete")
        self.assertEqual(board_state["sync_status_text"], "297/297")
        self.assertEqual(board_state["profile_fetched_count"], 186)
        self.assertEqual(board_state["profile_fetch_status_text"], "本次 LinkedIn Profile 已取回 186/297")
        # Card materialization (112) and profile-fetch (186) numerators must diverge: profiles fetched
        # must NOT drag the card count up. The card count is the honest display-ready count (cards
        # materialized of 186 fetched / 297 required); inferring 186 cards from the profile-fetch lane is
        # exactly the row-shell anti-pattern this test guards against.
        self.assertEqual(board_state["card_materialization_status_text"], "卡片详情已合入看板 112/297")
        self.assertTrue(board_state["delta_profile_denominator_promoted"])

    def test_partial_current_snapshot_overlay_preserves_stage1_denominator(self) -> None:
        job_id = "job_partial_current_overlay_stage1_denominator"
        snapshot_id = "20260514T040742"
        request = JobRequest.from_payload(
            {
                "raw_user_request": "帮我找OpenAI做Agent方向的人",
                "target_company": "OpenAI",
                "keywords": ["Agent"],
                "target_scope": "scoped_search",
            }
        )
        visible_candidates = [
            Candidate(
                candidate_id=f"agent_visible_{index}",
                name_en=f"Agent Visible {index}",
                display_name=f"Agent Visible {index}",
                category="employee",
                target_company="OpenAI",
                organization="OpenAI",
                employment_status="current",
                role="Research Engineer",
                linkedin_url=f"https://www.linkedin.com/in/agent-visible-{index}/",
                metadata={
                    "has_profile_detail": True,
                    "experience_lines": ["2025~Present, OpenAI, Agent Systems"],
                    "education_lines": ["Example University"],
                    "profile_capture_kind": "provider_profile_detail",
                },
            )
            for index in range(1, 3)
        ]
        snapshot_dir, _candidate_doc_path = self._write_company_snapshot_candidate_documents(
            target_company="OpenAI",
            snapshot_id=snapshot_id,
            candidates=[candidate.to_record() for candidate in visible_candidates],
        )
        self.store.save_job(
            job_id=job_id,
            job_type="workflow",
            status="running",
            stage="acquiring",
            request_payload=request.to_record(),
            plan_payload={},
            summary_payload={},
        )
        self.store.upsert_job_result_lifecycle(
            job_id=job_id,
            fields={
                "phase": "current_snapshot_materializing",
                "state": "current_snapshot_materializing",
                "current_snapshot_id": snapshot_id,
                "served_snapshot_id": snapshot_id,
                "served_candidate_count": 0,
                "expected_candidate_count": 0,
                "delta_profile_progress_applicable": False,
                "delta_profile_progress_reason": "not_applicable_live_roster_stage1",
                "stage1_current_search_returned_count": 4,
                "stage1_former_search_returned_count": 1,
                "stage1_deduped_candidate_count": 5,
                "stage1_deduped_profile_url_count": 5,
                "stage1_profile_fetch_required_count": 5,
                "stage1_profile_fetched_count": 2,
                "source_validation_status": "validated",
                "metadata": {"delta_profile_denominator_promoted": False},
            },
        )

        partial_patch = self.orchestrator._publish_partial_board_visible_current_snapshot_overlay(  # noqa: SLF001
            job=self.store.get_job(job_id) or {},
            request=request,
            snapshot_dir=snapshot_dir,
            candidate_ids=[candidate.candidate_id for candidate in visible_candidates],
            reason="test_no_baseline_partial_current_overlay",
        )

        self.assertEqual(partial_patch["status"], "completed")
        lifecycle = self.store.get_job_result_lifecycle(job_id)
        assert lifecycle is not None
        self.assertEqual(lifecycle["served_candidate_count"], 2)
        self.assertEqual(lifecycle["expected_candidate_count"], 5)
        self.assertEqual(lifecycle["serving_projection_phase"], "partial_current_snapshot_overlay")
        self.assertEqual(lifecycle["state"], "current_snapshot_serving")
        result_count = self.orchestrator._public_progress_result_count(  # noqa: SLF001
            job_id=job_id,
            job=self.store.get_job(job_id) or {},
            ranked_result_count=0,
        )
        self.assertEqual(result_count, 5)
        progress = self.orchestrator.get_job_progress(job_id)
        assert progress is not None
        self.assertEqual(progress["progress"]["counters"]["result_count"], 5)
        board_state = dict(progress.get("board_runtime_state") or {})
        self.assertEqual(board_state["expected_candidate_count"], 5)
        self.assertEqual(board_state["served_candidate_count"], 2)
        self.assertEqual(board_state["sync_status_text"], "2/5")

