    def test_stage1_lanes_terminal_uses_discovery_lane_registry_for_scoped_search(self) -> None:
        job_id = "job_stage1_terminal_registry_scoped"
        request = JobRequest.from_payload(
            {
                "raw_user_request": "帮我找OpenAI做Agent方向的人",
                "target_company": "OpenAI",
                "keywords": ["Agent"],
                "execution_preferences": {"delta_baseline_snapshot_id": "20260506T070000"},
            }
        )
        self.store.save_job(
            job_id=job_id,
            job_type="workflow",
            status="running",
            stage="acquiring",
            request_payload=request.to_record(),
            plan_payload={},
            summary_payload={},
        )
        self.store.upsert_job_materialization_item(
            item_id=f"{job_id}:seed:current",
            job_id=job_id,
            target_company="OpenAI",
            snapshot_id="20260506T073020",
            item_kind=SEARCH_SEED_DISCOVERY_QUERY_ITEM_KIND,
            status="completed",
            phase="completed",
            source="test",
            reason="seed_discovery_completed",
        )

        self.assertTrue(
            self.orchestrator._stage1_lanes_terminal_for_job(  # noqa: SLF001
                job_id=job_id,
                request=request,
                snapshot_id="20260506T073020",
            )
        )
        self.assertFalse(
            self.orchestrator._stage1_lanes_terminal_for_job(  # noqa: SLF001
                job_id=job_id,
                request=request,
                snapshot_id="20260506T999999",
            ),
            msg="discovery-lane terminal state must be scoped to the requested snapshot",
        )

        waiting_handle = self.orchestrator.agent_runtime.begin_worker(
            job_id=job_id,
            request=request,
            plan_payload={},
            runtime_mode="workflow",
            lane_id="search_planner",
            worker_key="search_seed::waiting",
            stage="acquiring",
            span_name="search_seed:waiting",
            metadata={"recovery_kind": "search_seed_discovery"},
        )
        self.store.checkpoint_agent_worker(
            waiting_handle.worker_id,
            status="queued",
            checkpoint_payload={"stage": "waiting_remote_search", "recovery_kind": "search_seed_discovery"},
        )

        self.assertFalse(
            self.orchestrator._stage1_lanes_terminal_for_job(  # noqa: SLF001
                job_id=job_id,
                request=request,
                snapshot_id="20260506T073020",
            )
        )

    def test_stage1_lanes_terminal_uses_discovery_lane_registry_for_live_roster(self) -> None:
        job_id = "job_stage1_terminal_registry_live_roster"
        snapshot_id = "20260506T074044"
        request = JobRequest.from_payload(
            {
                "raw_user_request": "帮我找Lovable的全部成员",
                "target_company": "Lovable",
                "target_scope": "full_company_asset",
                "employment_statuses": ["current", "former"],
            }
        )
        self.store.save_job(
            job_id=job_id,
            job_type="workflow",
            status="running",
            stage="acquiring",
            request_payload=request.to_record(),
            plan_payload={},
            summary_payload={},
        )
        waiting_handle = self.orchestrator.agent_runtime.begin_worker(
            job_id=job_id,
            request=request,
            plan_payload={},
            runtime_mode="workflow",
            lane_id="acquisition_specialist",
            worker_key="harvest_company_employees::waiting",
            stage="acquiring",
            span_name="harvest_company_employees:waiting",
            metadata={"recovery_kind": "harvest_company_employees"},
        )
        self.store.checkpoint_agent_worker(
            waiting_handle.worker_id,
            status="queued",
            checkpoint_payload={"stage": "waiting_remote_harvest", "recovery_kind": "harvest_company_employees"},
        )
        self.assertFalse(
            self.orchestrator._stage1_lanes_terminal_for_job(  # noqa: SLF001
                job_id=job_id,
                request=request,
                snapshot_id=snapshot_id,
            )
        )

        self.orchestrator.agent_runtime.complete_worker(
            waiting_handle,
            status="completed",
            checkpoint_payload={"stage": "completed", "recovery_kind": "harvest_company_employees"},
            output_payload={"inline_incremental_apply": {"snapshot_id": snapshot_id}},
        )

        self.assertFalse(
            self.orchestrator._stage1_lanes_terminal_for_job(  # noqa: SLF001
                job_id=job_id,
                request=request,
                snapshot_id=snapshot_id,
            ),
            msg="live-roster terminal detection must use the durable discovery-lane item, not worker markers",
        )
        self.store.upsert_job_materialization_item(
            item_id=f"{job_id}:live_roster_discovery_lane:{snapshot_id}",
            job_id=job_id,
            target_company="Lovable",
            snapshot_id=snapshot_id,
            item_kind=LIVE_ROSTER_DISCOVERY_LANE_ITEM_KIND,
            source="test",
            reason="live_roster_discovery_lane_materialized",
            status="completed",
            phase="completed",
        )

        self.assertTrue(
            self.orchestrator._stage1_lanes_terminal_for_job(  # noqa: SLF001
                job_id=job_id,
                request=request,
                snapshot_id=snapshot_id,
            )
        )

    def test_company_roster_apply_records_live_roster_discovery_lane_item(self) -> None:
        job_id = "job_live_roster_discovery_lane_apply_item"
        snapshot_id = "20260506T080001"
        snapshot_dir = Path(self.tempdir.name) / "snapshots" / snapshot_id
        snapshot_dir.mkdir(parents=True)

        with mock.patch.object(
            self.orchestrator.snapshot_materializer,
            "apply_company_roster_workers_to_snapshot",
            return_value={
                "status": "applied",
                "snapshot_id": snapshot_id,
                "worker_ids": [101],
                "entry_count": 12,
                "candidate_count": 12,
                "completion_status": "completed",
            },
        ):
            result = self.orchestrator._apply_background_company_roster_workers_to_snapshot(  # noqa: SLF001
                snapshot_dir=snapshot_dir,
                pending_workers=[{"worker_id": 101}],
                job_id=job_id,
            )

        self.assertEqual(result["status"], "applied")
        # W6 cutover: the live-roster discovery-lane terminal contract is
        # recorded as a durable CompletionProofRecorded workflow event
        # (proof_key stage1_lane:live_roster:<snapshot_id>:<item_id>), not a
        # job_materialization_items row; _stage1_lanes_terminal_for_job reads
        # exactly these proof events.
        item_id = f"{job_id}:live_roster_discovery_lane:{snapshot_id}"
        lane_proofs = [
            dict(dict(event).get("payload") or {})
            for event in self.store.list_workflow_events(legacy_job_workflow_run_id(job_id), limit=0)
            if str(dict(event).get("event_type") or "") == "CompletionProofRecorded"
            and str(dict(dict(event).get("payload") or {}).get("proof_key") or "").startswith(
                f"stage1_lane:live_roster:{snapshot_id}:"
            )
        ]
        self.assertEqual(len(lane_proofs), 1, lane_proofs)
        proof = lane_proofs[0]
        self.assertEqual(proof["item_id"], item_id)
        self.assertEqual(proof["item_kind"], LIVE_ROSTER_DISCOVERY_LANE_ITEM_KIND)
        self.assertEqual(proof["status"], "completed")
        self.assertEqual(proof["snapshot_id"], snapshot_id)
        self.assertEqual(proof["source_worker_ids"], [101])
        # The legacy materialization-items write path stays retired.
        self.assertEqual(self.store.get_job_materialization_item(item_id), {})

