        self.assertEqual([patch["sequence_index"] for patch in patches], [1, 2, 3])
        self.assertEqual(patches[-1]["served_candidate_count"], 6)
        self.assertNotEqual(patches[0]["patch_id"], patches[-1]["patch_id"])

