    def test_full_snapshot_board_visible_defers_roster_only_cards(self) -> None:
        # Slice 5 contract: deferral is now a 3-axis check. The patch is
        # deferred only when display_ready=0 AND needs_profile_completion=0
        # AND low_profile_richness=0 (pure shell roster rows with no provider
        # attempt evidence). Roster rows that already carry a LinkedIn URL
        # without fetched detail count as needs_profile_completion>0 and now
        # publish so discovery is visible — the frontend candidate-sync
        # numerator continues to read display_ready_candidate_count, not
        # published_candidate_count.
        job_id = "job_roster_only_full_snapshot_not_board_visible"
        snapshot_id = "20260420T151500"
        request = JobRequest.from_payload(
            {
                "raw_user_request": "帮我找Lovable的全部成员",
                "target_company": "Lovable",
                "target_scope": "full_company_asset",
                "categories": ["employee"],
                "employment_statuses": ["current"],
                "top_k": 10,
            }
        )
        snapshot_dir = self.settings.company_assets_dir / "lovable" / snapshot_id
        snapshot_dir.mkdir(parents=True, exist_ok=True)
        # Pure shell roster rows: no LinkedIn URL means no provider attempt
        # has been made yet. display_ready / needs_profile_completion /
        # low_profile_richness are all zero.
        candidates = [
            Candidate(
                candidate_id=f"lovable_roster_only_{index}",
                name_en=f"Lovable Roster Only {index}",
                display_name=f"Lovable Roster Only {index}",
                category="employee",
                target_company="Lovable",
                organization="Lovable",
                employment_status="current",
                role="Engineer",
            )
            for index in range(1, 4)
        ]
        candidate_documents_path = snapshot_dir / "candidate_documents.json"
        candidate_documents_path.write_text(
            json.dumps(
                {
                    "snapshot": {
                        "snapshot_id": snapshot_id,
                        "target_company": "Lovable",
                        "company_identity": {
                            "requested_name": "Lovable",
                            "canonical_name": "Lovable",
                            "company_key": "lovable",
                        },
                    },
                    "target_company": "Lovable",
                    "candidates": [candidate.to_record() for candidate in candidates],
                    "evidence": [],
                    "candidate_count": len(candidates),
                    "evidence_count": 0,
                },
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
        self.store.save_job(
            job_id=job_id,
            job_type="workflow",
            status="running",
            stage="acquiring",
            request_payload=request.to_record(),
            plan_payload={},
            summary_payload={},
        )

        patch = self.orchestrator._publish_full_snapshot_board_visible_serving(  # noqa: SLF001
            job=self.store.get_job(job_id) or {},
            request=request,
            snapshot_dir=snapshot_dir,
            sync_result={
                "status": "completed",
                "candidate_count": len(candidates),
                "artifact_paths": {"manifest": str(candidate_documents_path)},
            },
            worker_kind="company_roster",
            reason="test_roster_only_defers",
        )

        self.assertEqual(patch["status"], "deferred")
        self.assertEqual(patch["reason"], "board_visible_pure_shell_roster_rows")
        summary = dict(patch["card_materialization_summary"])
        self.assertEqual(int(summary.get("display_ready_candidate_count") or 0), 0)
        self.assertEqual(int(summary.get("needs_profile_completion_candidate_count") or 0), 0)
        self.assertEqual(int(summary.get("low_profile_richness_candidate_count") or 0), 0)
        self.assertEqual(self.store.list_job_board_visible_patches(job_id=job_id, snapshot_id=snapshot_id), [])
        self.assertIsNone(self.store.get_job_result_view(job_id=job_id))

    def test_job_materialization_item_claim_is_ordered_idempotent_and_retryable(self) -> None:
        item = self.store.upsert_job_materialization_item(
            item_id="job_board_apply_item|20260420T130000|delta_1",
            job_id="job_board_apply_item",
            target_company="OpenAI",
            snapshot_id="20260420T130000",
            baseline_snapshot_id="20260420T120000",
            item_kind="board_visible_delta_apply",
            source="test",
            reason="partial_board_visible",
            candidate_ids=["delta_1", "delta_1"],
            source_worker_ids=[7, 7],
            idempotency_key="job_board_apply_item|20260420T130000|delta_1",
        )
        self.assertEqual(item["status"], "queued")
        self.assertEqual(item["candidate_ids"], ["delta_1"])
        self.assertEqual(item["source_worker_ids"], [7])

        claimed = self.store.claim_job_materialization_item(
            item["item_id"],
            lease_owner="test-owner",
            lease_seconds=60,
        )
        self.assertEqual(claimed["status"], "running")
        self.assertEqual(claimed["phase"], "applying")
        self.assertEqual(claimed["attempt_count"], 1)
        duplicate_claim = self.store.claim_job_materialization_item(
            item["item_id"],
            lease_owner="second-owner",
            lease_seconds=60,
        )
        self.assertEqual(duplicate_claim, {})
        # Expire the lease on the AUTHORITATIVE row (PG) — a SQLite-shadow
        # UPDATE would leave the exercised PG row untouched.
        self.store._control_plane_postgres.execute_non_query(  # noqa: SLF001
            """
            UPDATE job_materialization_items
            SET lease_expires_at = '2000-01-01 00:00:00'
            WHERE item_id = %s
            """,
            (item["item_id"],),
        )
        ready_after_stale_lease = self.store.list_ready_job_materialization_items(
            job_id="job_board_apply_item",
            item_kind="board_visible_delta_apply",
            limit=5,
        )
        self.assertEqual([row["item_id"] for row in ready_after_stale_lease], [item["item_id"]])
        reclaimed = self.store.claim_job_materialization_item(
            item["item_id"],
            lease_owner="reclaim-owner",
            lease_seconds=60,
        )
        self.assertEqual(reclaimed["status"], "running")
        self.assertEqual(reclaimed["lease_owner"], "reclaim-owner")
        self.assertEqual(reclaimed["attempt_count"], 2)
        duplicate_enqueue = self.store.upsert_job_materialization_item(
            item_id=item["item_id"],
            job_id="job_board_apply_item",
            target_company="OpenAI",
            snapshot_id="20260420T130000",
            baseline_snapshot_id="20260420T120000",
            candidate_ids=["delta_1"],
        )
        self.assertEqual(duplicate_enqueue["status"], "running")
        self.assertEqual(duplicate_enqueue["lease_owner"], "reclaim-owner")

        retryable = self.store.mark_job_materialization_item_failed(
            item["item_id"],
            error_text="overlay temporarily unavailable",
            retryable=True,
            retry_delay_seconds=1,
        )
        self.assertEqual(retryable["status"], "failed_retryable")
        self.assertEqual(retryable["phase"], "retry_wait")
        self.assertEqual(retryable["last_error"], "overlay temporarily unavailable")

        completed = self.store.mark_job_materialization_item_completed(
            item["item_id"],
            result_patch_id="patch-1",
            result_view_id="view-1",
            serving_projection_id="/tmp/projection.json",
        )
        self.assertEqual(completed["status"], "completed")
        self.assertEqual(completed["result_patch_id"], "patch-1")
        self.assertEqual(completed["serving_projection_id"], "/tmp/projection.json")

        after_terminal_enqueue = self.store.upsert_job_materialization_item(
            item_id=item["item_id"],
            job_id="job_board_apply_item",
            target_company="OpenAI",
            snapshot_id="20260420T130000",
            candidate_ids=["delta_1"],
        )
        self.assertEqual(after_terminal_enqueue["status"], "completed")

