        self.assertEqual(returned_population, 223)
        self.assertEqual(progress["deduped_candidate_count"], 223)
        self.assertEqual(progress["deduped_profile_url_count"], 223)
        self.assertEqual(progress["profile_fetch_required_count"], 223)

