    def test_job_result_lifecycle_writer_stage1_live_roster_sets_expected_without_delta_counters(self) -> None:
        """Live-roster Stage 1 is provider work, but it is not baseline-delta
        progress. The lifecycle should expose expected population size without
        labelling the job as full-local reuse or filling delta counters."""

        self.orchestrator.initialize_job_result_lifecycle(
            job_id="job_lovable_live_roster_stage1",
            request=JobRequest.from_payload(
                {
                    "raw_user_request": "帮我找Lovable的全部成员",
                    "target_company": "Lovable",
                }
            ),
            plan=hydrate_sourcing_plan(
                self.orchestrator.plan_workflow(
                    {
                        "raw_user_request": "帮我找Lovable的全部成员",
                        "target_company": "Lovable",
                    }
                )["plan"]
            ),
            workflow_kind="linkedin_stage_1",
        )
        self.store.upsert_job_result_lifecycle(
            job_id="job_lovable_live_roster_stage1",
            fields={
                "served_candidate_count": 0,
                "expected_candidate_count": 145,
                "source_validation_status": "validated",
            },
        )

        self.orchestrator.update_job_result_lifecycle_from_stage1(
            job_id="job_lovable_live_roster_stage1",
            linkedin_stage_1_progress={
                "current_search_returned_count": 120,
                "former_search_returned_count": 25,
                "deduped_candidate_count": 140,
                "deduped_profile_url_count": 140,
                "profile_fetch_required_count": 140,
                "profile_fetched_count": 72,
            },
            projection_source_snapshot_id="20260504T165620",
            is_delta_workflow=False,
            # Stage 1 lanes terminal so the live-roster denominator is
            # promoted to the projected population for this run.
            stage1_lanes_terminal=True,
        )

        row = self.store.get_job_result_lifecycle("job_lovable_live_roster_stage1")
        assert row is not None
        self.assertEqual(row["expected_candidate_count"], 140)
        self.assertEqual(row["stage1_profile_fetch_required_count"], 140)
        self.assertEqual(row["stage1_profile_fetched_count"], 72)
        self.assertEqual(row["delta_profile_progress_applicable"], 0)
        self.assertEqual(row["delta_profile_required_count"], 0)
        self.assertEqual(row["delta_profile_progress_reason"], "not_applicable_live_roster_stage1")

