        progress = self.orchestrator.get_job_progress(job_id)
        dashboard = self.orchestrator.get_job_dashboard(job_id)
        page = self.orchestrator.get_job_candidate_page(job_id, offset=0, limit=24, lightweight=True)

        for payload in (progress, dashboard, page):
            assert payload is not None
            board = dict(payload.get("board_runtime_state") or {})
            stage1 = dict(payload.get("linkedin_stage_1_progress") or {})
            self.assertEqual(board["expected_candidate_count"], 297)
            self.assertEqual(board["profile_fetch_required_count"], 297)
            self.assertEqual(board["profile_fetched_count"], 223)
            self.assertEqual(stage1["profile_fetch_required_count"], 297)
            self.assertEqual(stage1["profile_fetched_count"], 223)
            self.assertEqual(stage1["profile_pending_count"], 74)

        after = dict(self.store.get_job_result_lifecycle(job_id) or {})
        self.assertEqual(before.get("stage1_profile_fetched_count"), 223)
        self.assertEqual(after.get("stage1_profile_fetched_count"), 223)
        self.assertEqual(before.get("updated_at"), after.get("updated_at"))

