    def test_job_result_lifecycle_validated_stage1_row_is_not_mutated_by_public_reads(self) -> None:
        """Once the Stage 1 writer has persisted a validated row with a
        `projection_source_snapshot_id`, public reads (`/dashboard`,
        `/progress`, `/candidates`) must not regress its canonical fields.

        This is the no-public-read-mutation invariant from slice 3."""

        baseline_snapshot_id = "20260420T120000"
        self._write_materialized_snapshot_view(
            target_company="OpenAI",
            snapshot_id=baseline_snapshot_id,
            candidates=[
                {"candidate_id": "baseline_member_1", "display_name": "Baseline One"},
                {"candidate_id": "baseline_member_2", "display_name": "Baseline Two"},
            ],
        )
        request = JobRequest.from_payload(
            {
                "raw_user_request": "帮我找OpenAI做Agent方向的人",
                "target_company": "OpenAI",
                "keywords": ["Agent"],
                "execution_preferences": {"delta_baseline_snapshot_id": baseline_snapshot_id},
            }
        )
        plan = hydrate_sourcing_plan(self.orchestrator.plan_workflow(request.to_record())["plan"])
        plan.asset_reuse_plan = {
            "baseline_reuse_available": True,
            "requires_delta_acquisition": True,
            "planner_mode": "baseline_reuse_with_delta",
            "baseline_snapshot_id": baseline_snapshot_id,
            "baseline_candidate_count": 2,
        }
        job_id = self.orchestrator._create_workflow_job(request, plan)  # noqa: SLF001

        # Simulate Stage 1 writer running with a coherent projection.
        self.orchestrator.update_job_result_lifecycle_from_stage1(
            job_id=job_id,
            linkedin_stage_1_progress={
                "current_search_returned_count": 5,
                "former_search_returned_count": 1,
                "deduped_candidate_count": 6,
                "deduped_profile_url_count": 6,
                "profile_fetch_required_count": 6,
                "profile_fetched_count": 2,
            },
            projection_source_snapshot_id="20260430T120000",
            is_delta_workflow=True,
        )

        before = dict(self.store.get_job_result_lifecycle(job_id) or {})
        # Three public reads; none should regress canonical Stage 1 fields.
        self.orchestrator.get_job_dashboard(job_id)
        self.orchestrator.get_job_progress(job_id)
        self.orchestrator.get_job_candidate_page(job_id, offset=0, limit=10, lightweight=True)
        after = dict(self.store.get_job_result_lifecycle(job_id) or {})

        for field in (
            "stage1_current_search_returned_count",
            "stage1_former_search_returned_count",
            "stage1_deduped_candidate_count",
            "stage1_profile_fetch_required_count",
            "stage1_profile_fetched_count",
            "delta_profile_required_count",
            "delta_profile_fetched_count",
            "projection_source_snapshot_id",
        ):
            self.assertEqual(
                before.get(field), after.get(field), msg=f"public read regressed Stage 1 field {field!r}"
            )

    def test_job_result_lifecycle_stage1_event_time_write_before_public_read(self) -> None:
        """Stage 1 lifecycle projection must be written at workflow event-time,
        not at public-read time. Public reads must find the row already up to
        date and must not mutate it.

        This is the slice-4 invariant: event-driven canonical writes, not
        public-read repair.

        This test proves that once the Stage 1 writer has run (either at
        event-time or via the slice-3 public-read seam), subsequent public
        reads do NOT mutate the canonical row."""

        baseline_snapshot_id = "20260420T120000"
        self._write_materialized_snapshot_view(
            target_company="OpenAI",
            snapshot_id=baseline_snapshot_id,
            candidates=[
                {"candidate_id": "baseline_member_1", "display_name": "Baseline One"},
            ],
        )
        request = JobRequest.from_payload(
            {
                "raw_user_request": "帮我找OpenAI做Agent方向的人",
                "target_company": "OpenAI",
                "keywords": ["Agent"],
                "execution_preferences": {"delta_baseline_snapshot_id": baseline_snapshot_id},
            }
        )
        plan = hydrate_sourcing_plan(self.orchestrator.plan_workflow(request.to_record())["plan"])
        plan.asset_reuse_plan = {
            "baseline_reuse_available": True,
            "requires_delta_acquisition": True,
            "planner_mode": "baseline_reuse_with_delta",
            "baseline_snapshot_id": baseline_snapshot_id,
            "baseline_candidate_count": 1,
        }
        job_id = self.orchestrator._create_workflow_job(request, plan)  # noqa: SLF001

        # Simulate that the event-time writer (or slice-3 public-read writer)
        # has already run and populated the Stage 1 fields.
        self.orchestrator.update_job_result_lifecycle_from_stage1(
            job_id=job_id,
            linkedin_stage_1_progress={
                "current_search_returned_count": 5,
                "former_search_returned_count": 2,
                "deduped_candidate_count": 7,
                "deduped_profile_url_count": 7,
                "profile_fetch_required_count": 7,
                "profile_fetched_count": 3,
            },
            projection_source_snapshot_id="20260430T120000",
            is_delta_workflow=True,
        )

        # The row should have Stage 1 fields populated.
        row_before_reads = self.store.get_job_result_lifecycle(job_id)
        assert row_before_reads is not None
        self.assertGreater(
            row_before_reads.get("stage1_current_search_returned_count", 0),
            0,
            msg="Stage 1 writer must have populated counters",
        )
        self.assertTrue(
            str(row_before_reads.get("projection_source_snapshot_id") or "").strip(),
            msg="Stage 1 writer must have set projection_source_snapshot_id",
        )

        # Now public reads: they must NOT mutate the canonical row.
        before = dict(self.store.get_job_result_lifecycle(job_id) or {})
        self.orchestrator.get_job_dashboard(job_id)
        self.orchestrator.get_job_progress(job_id)
        self.orchestrator.get_job_candidate_page(job_id, offset=0, limit=10, lightweight=True)
        after = dict(self.store.get_job_result_lifecycle(job_id) or {})

        for field in (
            "stage1_current_search_returned_count",
            "stage1_former_search_returned_count",
            "stage1_deduped_candidate_count",
            "stage1_profile_fetch_required_count",
            "stage1_profile_fetched_count",
            "delta_profile_required_count",
            "delta_profile_fetched_count",
            "projection_source_snapshot_id",
        ):
            self.assertEqual(
                before.get(field),
                after.get(field),
                msg=f"public read mutated Stage 1 field {field!r} (slice-4 invariant violated)",
            )

    def test_job_result_lifecycle_baseline_delta_overlay_for_health_whisper_shape(self) -> None:
        """Health/Whisper regression: baseline+delta job where current lane
        returns 0 and former lane returns >0 must serve baseline+delta overlay,
        not raw delta-only. The canonical lifecycle row must record
        served_snapshot_id = current (not baseline), served_candidate_count =
        baseline + delta.

        This is the slice-5 invariant: materialization/repoint event-time
        writes prevent raw delta-only result views for baseline+delta jobs."""

        baseline_snapshot_id = "20260420T120000"
        current_snapshot_id = "20260430T130000"
        self._write_materialized_snapshot_view(
            target_company="OpenAI",
            snapshot_id=baseline_snapshot_id,
            candidates=[
                {"candidate_id": "baseline_member_1", "display_name": "Baseline One"},
                {"candidate_id": "baseline_member_2", "display_name": "Baseline Two"},
            ],
        )
        self._write_materialized_snapshot_view(
            target_company="OpenAI",
            snapshot_id=current_snapshot_id,
            candidates=[
                {"candidate_id": "baseline_member_1", "display_name": "Baseline One"},
                {"candidate_id": "baseline_member_2", "display_name": "Baseline Two"},
                {
                    "candidate_id": "delta_former_1",
                    "display_name": "Delta Former One",
                    "employment_status": "former",
                },
            ],
        )
        request = JobRequest.from_payload(
            {
                "raw_user_request": "帮我找OpenAI做Agent方向的人",
                "target_company": "OpenAI",
                "keywords": ["Agent"],
                "employment_statuses": ["current", "former"],
                "execution_preferences": {"delta_baseline_snapshot_id": baseline_snapshot_id},
            }
        )
        plan = hydrate_sourcing_plan(self.orchestrator.plan_workflow(request.to_record())["plan"])
        plan.asset_reuse_plan = {
            "baseline_reuse_available": True,
            "requires_delta_acquisition": True,
            "planner_mode": "baseline_reuse_with_delta",
            "baseline_snapshot_id": baseline_snapshot_id,
            "baseline_candidate_count": 2,
        }
        job_id = self.orchestrator._create_workflow_job(request, plan)  # noqa: SLF001

        # Simulate the materialization event-time writer being called after
        # the baseline+delta overlay result view is published.
        self.orchestrator.update_job_result_lifecycle_from_materialization(
            job_id=job_id,
            served_snapshot_id=current_snapshot_id,
            served_candidate_count=3,
            current_snapshot_id=current_snapshot_id,
            delta_profile_required_count=1,
            delta_profile_fetched_count=1,
            delta_profile_materialized_count=1,
        )

        # The canonical lifecycle row must record the overlay serving state.
        row = self.store.get_job_result_lifecycle(job_id)
        assert row is not None
        self.assertEqual(
            row["served_snapshot_id"],
            current_snapshot_id,
            msg="served_snapshot_id must be current (overlay), not baseline",
        )
        self.assertEqual(
            row["served_candidate_count"],
            3,
            msg="served_candidate_count must be baseline (2) + delta (1) = 3",
        )
        self.assertEqual(
            row["delta_profile_materialized_count"],
            1,
            msg="delta_profile_materialized_count must reflect the materialized delta",
        )
        self.assertEqual(
            row["source_validation_status"],
            "validated",
            msg="materialization writer must mark row as validated",
        )

        # Public reads must observe the same canonical row and must not mutate it.
        # Slice 5: The canonical reader fast path no longer requires a stored
        # result_view to exist. A validated row is trusted even when no
        # result_view has been persisted yet.
        before = dict(self.store.get_job_result_lifecycle(job_id) or {})
        dashboard = self.orchestrator.get_job_dashboard(job_id)
        after = dict(self.store.get_job_result_lifecycle(job_id) or {})
        assert dashboard is not None
        lifecycle_dashboard = dict(dashboard["result_view_lifecycle"])
        self.assertEqual(lifecycle_dashboard["served_snapshot_id"], current_snapshot_id)
        self.assertEqual(lifecycle_dashboard["served_candidate_count"], 3)
        self.assertEqual(lifecycle_dashboard["delta_profile_materialized_count"], 1)
        for field in ("served_snapshot_id", "served_candidate_count", "delta_profile_materialized_count"):
            self.assertEqual(
                before.get(field),
                after.get(field),
                msg=f"public read mutated materialization field {field!r}",
            )

        # Cross-API consistency: /progress and /candidates must return identical lifecycle.
        progress = self.orchestrator.get_job_progress(job_id)
        assert progress is not None
        lifecycle_progress = dict(progress["result_view_lifecycle"])
        self.assertEqual(lifecycle_progress["served_snapshot_id"], current_snapshot_id)
        self.assertEqual(lifecycle_progress["served_candidate_count"], 3)
        self.assertEqual(lifecycle_progress["delta_profile_materialized_count"], 1)

        candidates_page = self.orchestrator.get_job_candidate_page(job_id, offset=0, limit=50)
        assert candidates_page is not None
        lifecycle_candidates = dict(candidates_page["result_view_lifecycle"])
        self.assertEqual(lifecycle_candidates["served_snapshot_id"], current_snapshot_id)
        self.assertEqual(lifecycle_candidates["served_candidate_count"], 3)
        self.assertEqual(lifecycle_candidates["delta_profile_materialized_count"], 1)

    def test_job_result_lifecycle_validated_row_without_result_view_requires_serving_proof(self) -> None:
        """A validated lifecycle row is not enough to prove public serving.

        Public reads must not fall back to legacy lifecycle projection, but
        they also must not expose served rows until a pageable serving artifact
        exists.
        """

        request = JobRequest.from_payload(
            {
                "raw_user_request": "帮我找Anthropic做Agent方向的人",
                "target_company": "Anthropic",
                "keywords": ["Agent"],
                "employment_statuses": ["current"],
            }
        )
        plan = hydrate_sourcing_plan(self.orchestrator.plan_workflow(request.to_record())["plan"])
        job_id = self.orchestrator._create_workflow_job(request, plan)  # noqa: SLF001

        # Simulate the materialization writer recording lifecycle state before
        # the result_view upsert completes.
        current_snapshot_id = "20260501T140000"
        self.orchestrator.update_job_result_lifecycle_from_materialization(
            job_id=job_id,
            served_snapshot_id=current_snapshot_id,
            served_candidate_count=42,
            current_snapshot_id=current_snapshot_id,
            delta_profile_required_count=0,
            delta_profile_fetched_count=0,
            delta_profile_materialized_count=0,
        )

        # Verify the canonical row is validated and has no result_view yet.
        row = self.store.get_job_result_lifecycle(job_id)
        assert row is not None
        self.assertEqual(row["source_validation_status"], "validated")
        self.assertEqual(row["served_snapshot_id"], current_snapshot_id)
        self.assertEqual(row["served_candidate_count"], 42)

        result_view = self.store.get_job_result_view(job_id=job_id)
        self.assertIsNone(result_view, msg="result_view must not exist yet")

        # Public reads must consume the canonical row without mutating it, but
        # fail closed because no result_view or normalized serving artifact can
        # actually serve candidate-board rows yet.
        before = dict(self.store.get_job_result_lifecycle(job_id) or {})
        dashboard = self.orchestrator.get_job_dashboard(job_id)
        after = dict(self.store.get_job_result_lifecycle(job_id) or {})
        assert dashboard is not None
        lifecycle = dict(dashboard["result_view_lifecycle"])
        self.assertEqual(lifecycle["served_snapshot_id"], current_snapshot_id)
        self.assertEqual(lifecycle["state"], "current_snapshot_materializing")
        self.assertEqual(lifecycle["served_candidate_count"], 0)
        board_state = dict(dashboard["board_runtime_state"])
        self.assertEqual(board_state["phase"], "awaiting_publication")
        self.assertEqual(board_state["publication_status"], "pending")
        self.assertEqual(board_state["expected_candidate_count"], 42)
        self.assertEqual(board_state["published_candidate_count"], 0)
        # Public read must not mutate the canonical row.
        self.assertEqual(before.get("served_snapshot_id"), after.get("served_snapshot_id"))
        self.assertEqual(before.get("served_candidate_count"), after.get("served_candidate_count"))

    def test_job_result_lifecycle_terminal_invariant_baseline_served_incomplete_delta(self) -> None:
        """Terminal invariant: a completed job at stale baseline with incomplete
        delta materialization must not report stable current serving. The
        canonical reader must project `current_snapshot_materializing` or
        `delta_applying`, never `baseline_serving` or `results`."""

        baseline_snapshot_id = "20260420T120000"
        current_snapshot_id = "20260430T130000"
        request = JobRequest.from_payload(
            {
                "raw_user_request": "帮我找OpenAI做Agent方向的人",
                "target_company": "OpenAI",
                "keywords": ["Agent"],
                "employment_statuses": ["current", "former"],
                "execution_preferences": {"delta_baseline_snapshot_id": baseline_snapshot_id},
            }
        )
        plan = hydrate_sourcing_plan(self.orchestrator.plan_workflow(request.to_record())["plan"])
        plan.asset_reuse_plan = {
            "baseline_reuse_available": True,
            "requires_delta_acquisition": True,
            "planner_mode": "baseline_reuse_with_delta",
            "baseline_snapshot_id": baseline_snapshot_id,
            "baseline_candidate_count": 10,
        }
        job_id = self.orchestrator._create_workflow_job(request, plan)  # noqa: SLF001

        # Simulate the job reaching terminal state while still serving baseline
        # and delta materialization incomplete.
        self.orchestrator.update_job_result_lifecycle_from_materialization(
            job_id=job_id,
            served_snapshot_id=baseline_snapshot_id,
            served_candidate_count=10,
            current_snapshot_id=current_snapshot_id,
            delta_profile_required_count=50,
            delta_profile_fetched_count=50,
            delta_profile_materialized_count=20,
        )
        # Mark the job as completed directly in the store — on the
        # AUTHORITATIVE PG row, not the SQLite compatibility shadow.
        self.store._control_plane_postgres.execute_non_query(  # noqa: SLF001
            "UPDATE jobs SET status = 'completed', stage = 'completed' WHERE job_id = %s",
            (job_id,),
        )

        # The canonical reader must apply the terminal-phase invariant and must
        # not report stable `results` or `baseline_serving`.
        dashboard = self.orchestrator.get_job_dashboard(job_id)
        assert dashboard is not None
        lifecycle = dict(dashboard["result_view_lifecycle"])
        state = str(lifecycle.get("state") or "").strip().lower()
        self.assertNotEqual(
            state,
            "baseline_serving",
            msg="terminal job at stale baseline with incomplete delta must not report baseline_serving",
        )
        self.assertNotEqual(
            state,
            "results",
            msg="terminal job at stale baseline with incomplete delta must not report results",
        )
        self.assertIn(
            state,
            {"current_snapshot_materializing", "delta_applying"},
            msg="terminal job at stale baseline with incomplete delta must report materializing or applying",
        )

