    def test_job_result_lifecycle_failed_workflow_writes_terminal_row(self) -> None:
        """Slice 7: When a workflow fails, mark_job_result_lifecycle_terminal(outcome='failed')
        must be called to write a terminal lifecycle row with outcome='failed'."""

        request = JobRequest.from_payload(
            {
                "raw_user_request": "帮我找Anthropic做Agent方向的人",
                "target_company": "Anthropic",
                "keywords": ["Agent"],
                "employment_statuses": ["current"],
            }
        )
        plan = hydrate_sourcing_plan(self.orchestrator.plan_workflow(request.to_record())["plan"])
        job_id = self.orchestrator._create_workflow_job(request, plan)  # noqa: SLF001

        # Simulate workflow failure by calling _mark_workflow_failed
        class FakeException(Exception):
            pass

        try:
            raise FakeException("Simulated workflow failure")
        except FakeException as exc:
            self.orchestrator._mark_workflow_failed(  # noqa: SLF001
                job_id=job_id,
                request=request,
                plan=plan,
                exc=exc,
            )

        # Verify job status is failed
        job = self.orchestrator.store.get_job(job_id)
        self.assertEqual(job["status"], "failed")
        self.assertEqual(job["stage"], "failed")

        # Verify lifecycle row was written with phase='failed' and state='failed'
        lifecycle_row = self.orchestrator.store.get_job_result_lifecycle(job_id)
        self.assertIsNotNone(lifecycle_row, "lifecycle row must exist after workflow failure")
        self.assertEqual(lifecycle_row["phase"], "failed")
        self.assertEqual(lifecycle_row["state"], "failed")
        self.assertEqual(lifecycle_row["phase_status"], "terminal")
        self.assertEqual(lifecycle_row["source_validation_status"], "validated")

        # Verify public APIs report failed state consistently
        dashboard = self.orchestrator._load_job_result_lifecycle(  # noqa: SLF001
            job_id=job_id,
            job=job,
            request=request,
        )
        self.assertEqual(dashboard["state"], "failed")

