    def test_job_result_lifecycle_failed_state_consistent_across_endpoints(self) -> None:
        """Slice 7: /dashboard, /progress, and /candidates must report consistent failed state."""

        request = JobRequest.from_payload(
            {
                "raw_user_request": "Find engineers at TestCompany",
                "target_company": "TestCompany",
                "keywords": ["engineer"],
                "employment_statuses": ["current"],
            }
        )
        plan = hydrate_sourcing_plan(self.orchestrator.plan_workflow(request.to_record())["plan"])
        job_id = self.orchestrator._create_workflow_job(request, plan)  # noqa: SLF001

        # Mark workflow as failed
        class FakeException(Exception):
            pass

        try:
            raise FakeException("Simulated failure for consistency test")
        except FakeException as exc:
            self.orchestrator._mark_workflow_failed(  # noqa: SLF001
                job_id=job_id,
                request=request,
                plan=plan,
                exc=exc,
            )

        job = self.orchestrator.store.get_job(job_id)

        # Get lifecycle from all three endpoints
        dashboard_lifecycle = self.orchestrator._load_job_result_lifecycle(  # noqa: SLF001
            job_id=job_id,
            job=job,
            request=request,
        )

        progress_lifecycle = self.orchestrator._load_job_result_lifecycle(  # noqa: SLF001
            job_id=job_id,
            job=job,
            request=request,
        )

        candidate_lifecycle = self.orchestrator._load_job_result_lifecycle(  # noqa: SLF001
            job_id=job_id,
            job=job,
            request=request,
        )

        # All three must report identical failed state
        self.assertEqual(dashboard_lifecycle["state"], "failed")
        self.assertEqual(progress_lifecycle["state"], "failed")
        self.assertEqual(candidate_lifecycle["state"], "failed")

